local config = {
  ui_story_5063_50630101_1_dialog_content = "(Aduh... Kepalaku.)",
  ui_story_5063_50630101_2_dialog_content = "(Aku pasti lebih lelah dari yang kubayangkan, sampai-sampai bisa tertidur di luar seperti ini.)",
  ui_story_5063_50630101_3_dialog_content = "(Untungnya aku baru saja bangun. Aku masih punya cukup waktu untuk menghadiri rapat berikutnya.)",
  ui_story_5063_50630101_4_dialog_content = "Tunggu sebentar, ya!",
  ui_story_5063_50630101_5_dialog_content = "Hmm?",
  ui_story_5063_50630101_6_dialog_content = "Saat ini, Hall of Justice sedang melakukan rapat tertutup. Orang yang tidak berwenang tidak diperbolehkan masuk.",
  ui_story_5063_50630101_7_dialog_content = "Apakah kalian penjaga baru, mungkin?",
  ui_story_5063_50630101_8_dialog_content = "Kebetulan saya adalah Hakim Ketua di sini di Balai Kehakiman.",
  ui_story_5063_50630101_9_dialog_content = "Saya akan mengadakan rapat penting yang akan segera dimulai. Tolong izinkan saya masuk agar saya bisa memulai persiapan.",
  ui_story_5063_50630101_10_dialog_content = "Kamu <color=#FFB400>berpakaian seperti ksatria</color>, namun kamu berani menyamar sebagai Hakim Ketua yang terhormat di tanah suci ini?",
  ui_story_5063_50630101_11_dialog_content = "Seorang dengan niat jahat seperti itu—bagaimana kami bisa membiarkan Anda menipu dengan seenaknya?!",
  ui_story_5063_50630101_12_dialog_content = "Saya sangat mengagumi dedikasi dan kejujuran Anda, tetapi saya benar-benar adalah Hakim Kepala Lumopolis! Jika Anda masih tidak percaya pada saya...",
  ui_story_5063_50630101_13_dialog_content = "Kamu tidak menyerah, ya? Sepertinya kami harus menahanmu untuk penyelidikan yang menyeluruh!",
  ui_story_5063_50630101_14_dialog_content = "Apa kaubilang?",
  ui_story_5063_50630101_15_dialog_content = "Berhenti di sana!!!",
  ui_story_5063_50630102_1_dialog_content = "(Mengapa tidak ada satupun penjaga ini yang mengenaliku?)",
  ui_story_5063_50630102_2_dialog_content = "(Juga... Kapan aku berganti menjadi seragam ksatria ini? Aku sama sekali tidak ingat melakukannya!)",
  ui_story_5063_50630102_3_dialog_content = "Berhenti! Jangan coba-coba lari!",
  ui_story_5063_50630102_4_dialog_content = "...",
  ui_story_5063_50630102_5_dialog_content = "Ini buruk. Dia akan segera menerobos masuk ke Hall of Justice!",
  ui_story_5063_50630102_6_dialog_content = "<color=#e8d9bb>Kriek—</color>",
  ui_story_5063_50630102_7_dialog_content = "Terang sekali... Apa itu benda?",
  ui_story_5063_50630102_8_dialog_content = "Mohon maaf, Hakim Ketua!",
  ui_story_5063_50630102_9_dialog_content = "(Apakah mereka... akhirnya mengenaliku?)",
  ui_story_5063_50630102_10_dialog_content = "Chief Judge, kami sangat minta maaf telah mengejutkan Anda! Kami akan segera menahan peniru jahat ini!",
  ui_story_5063_50630102_11_dialog_content = "(Penjaga... Sepertinya mereka tidak berbicara padaku.)",
  ui_story_5063_50630102_12_dialog_content = "Terima kasih atas bantuan kalian semua.",
  ui_story_5063_50630102_13_dialog_content = "Ini adalah Justice Knight baru di Hall of Justice, jadi mungkin dia belum familiar dengan aturan di sini.",
  ui_story_5063_50630102_14_dialog_content = "Saya akan memastikan untuk membimbingnya tentang cara bersikap di Hall of Justice. Sisanya, kalian bisa pergi dulu untuk sekarang.",
  ui_story_5063_50630102_15_dialog_content = "Ya, Hakim Ketua!",
  ui_story_5063_50630102_16_dialog_content = "... <color=#FFB400>Hakim Ketua</color>?!",
  ui_story_5063_50630102_17_dialog_content = "Tapi hanya satu orang yang bisa menjadi Hakim Ketua... Apa yang sebenarnya terjadi?!",
  ui_story_5063_50630102_18_dialog_content = "Masuk tanpa izin ke Aula Kehakiman, sungguh berani sekali Anda.",
  ui_story_5063_50630102_19_dialog_content = "Permisi? Saya Irridon, Chief Judge dari Lumopolis Hall of Justice, dan saya bebas untuk datang dan pergi sesuka hati...",
  ui_story_5063_50630102_20_dialog_content = "Sekarang katakan padaku, menurutmu apa yang sedang kamu lakukan di kursi milikku?",
  ui_story_5063_50630102_21_dialog_content = "Memiliki impian itu baik, tetapi Anda perlu menilai dengan cermat apakah Anda memiliki kemampuan untuk itu.",
  ui_story_5063_50630102_22_dialog_content = "Saya selalu menghargai anak muda yang memiliki aspirasi, tetapi bukan mereka yang terbuai dalam lamunan.",
  ui_story_5063_50630102_23_dialog_content = "Dapatkan pandangan yang jelas tentang posisi Anda. Jika Anda ingin terus melayani Hall of Justice...",
  ui_story_5063_50630102_24_dialog_content = "Mulai sekarang, ikuti kata-kata saya, dan perhatikan apa yang saya lakukan.",
  ui_story_5063_50630102_25_dialog_content = "\"Lakukan seperti yang kukatakan, dan perhatikan apa yang kulakukan...\" Tapi itu adalah <color=#FFB400>frasa favorit ayahku</color>! Kenapa kamu tahu itu?!",
  ui_story_5063_50630102_26_dialog_content = "Saya adalah penerus pilihan yang disukai oleh ayah Anda, Hakim Ketua Rodell.",
  ui_story_5063_50630102_27_dialog_content = "Jangan menganggap bahwa hanya karena ayah Anda adalah Hakim Ketua, Anda akan secara otomatis menjadi Hakim Ketua suatu hari nanti.",
  ui_story_5063_50630102_28_dialog_content = "Saat ini, Anda hanyalah seorang Justice Knight biasa yang baru di Balai Kehakiman.",
  ui_story_5063_50630102_29_dialog_content = "Aku... hanya seorang Justice Knight?",
  ui_story_5063_50630102_30_dialog_content = "Sepertinya kau benar-benar tenggelam dalam lamunan; belum bangun juga ya?",
  ui_story_5063_50630102_31_dialog_content = "(Mimpi... Benar, saya memang mengalami beberapa mimpi aneh pagi ini, tapi sekarang saya tidak bisa mengingat satupun dari mereka.)",
  ui_story_5063_50630102_32_dialog_content = "(A-Apakah aku bermimpi sepanjang waktu? Mengapa tadi aku merasa menjadi Hakim Ketua?",
  ui_story_5063_50630102_33_dialog_content = "(Mimpi-mimpi itu... Pasti sangat realistis sehingga saya mengira mereka benar-benar nyata!)",
  ui_story_5063_50630102_34_dialog_content = "(Jadi, sikapku terhadap para pengawal tadi... Di mata mereka, aku tidak berbeda dengan seorang pembohong!)",
  ui_story_5063_50630102_35_dialog_content = "Mohon maafkan sikap tidak sopan saya, Hakim Ketua...",
  ui_story_5063_50630102_36_dialog_content = "Yah, sikapmu memang terlihat tulus.",
  ui_story_5063_50630102_37_dialog_content = "Demi menghormati ayahmu, kali ini aku akan membiarkannya. Kembali dan renungkan perilakumu; bayar aku melalui tindakanmu.",
  ui_story_5063_50630102_38_dialog_content = "Sekarang, lakukan tanggung jawabmu sekarang.",
  ui_story_5063_50630102_39_dialog_content = "Terima kasih, Hakim Ketua!",
  ui_story_5063_50630102_40_dialog_content = "(Aku tidak percaya aku membuat kesalahan yang sangat buruk di hari pertamaku. Betapa memalukan.)",
  ui_story_5063_50630102_41_dialog_content = "(Terima kasih Tuhan Hakim Ketua cukup baik untuk mengabaikan pelanggaran yang saya lakukan...)",
  ui_story_5063_50630102_42_dialog_content = "<color=#e8d9bb>Klang!</color>",
  ui_story_5063_50630102_43_dialog_content = "Di mana Chief Judge?!",
  ui_story_5063_50630102_44_dialog_content = "Hakim Ketua!",
  ui_story_5063_50630102_45_dialog_content = "Saya rasa Anda salah. Chief Judge sedang duduk di sana.",
  ui_story_5063_50630102_46_dialog_content = "Tunjukkan identitasmu.",
  ui_story_5063_50630102_47_dialog_content = "Ketua Hakim, keluarga saya dan saya telah dituduh secara salah, dan kami berharap Anda dapat membantu kami mencari keadilan dan membersihkan nama kami!",
  ui_story_5063_50630102_48_dialog_content = "Jadi, apakah kamu dinyatakan bersalah?",
  ui_story_5063_50630102_49_dialog_content = "Setiap keputusan yang diberikan oleh Balai Kehakiman disahkan oleh Dewa Cahaya, tanpa ada ruang untuk kesalahan.",
  ui_story_5063_50630102_50_dialog_content = "Sebagai pihak yang bersalah, Anda menolak untuk mengakui kesalahan Anda dan menghadapi hukuman serta secara tidak sah menerobos masuk ke Balai Kehakiman, menghancurkan keputusan suci kami...",
  ui_story_5063_50630102_51_dialog_content = "Kamu benar-benar keji dan pantas dihukum lebih keras!",
  ui_story_5063_50630102_52_dialog_content = "...",
  ui_story_5063_50630102_53_dialog_content = "Humph! Sudah diduga, seharusnya aku tidak menaruh harapan pada Lumopolis sejak awal!",
  ui_story_5063_50630102_54_dialog_content = "Duduk di Hall of Justice dan berlagak sombong tidak berarti Anda benar-benar mewujudkan keadilan mutlak.",
  ui_story_5063_50630102_55_dialog_content = "Kau akan tahu. Aku akan menegakkan keadilan dengan caraku sendiri.",
  ui_story_5063_50630102_56_dialog_content = "Ini keterlaluan!!!",
  ui_story_5063_50630102_57_dialog_content = "Knight of Justice, kenapa kamu masih berdiri di sana?",
  ui_story_5063_50630102_58_dialog_content = "Justice Knight Irridon, siap atas perintah Anda!",
  ui_story_5063_50630102_59_dialog_content = "Pergi dan tangkap wanita gila itu! Jangan mengecewakanku lagi!",
  ui_story_5063_50630102_60_dialog_content = "Ya, Hakim Ketua!",
  ui_story_5063_50630201_1_dialog_content = "Tahan, berhenti di sana!",
  ui_story_5063_50630201_2_dialog_content = "Menyerah sekarang, dan kamu mungkin memiliki kesempatan untuk hukuman yang lebih ringan.",
  ui_story_5063_50630201_3_dialog_content = "Oh? Lalu katakan padaku, kejahatan apa yang sebenarnya telah aku lakukan, dan mengapa kau menangkapku?",
  ui_story_5063_50630201_4_dialog_content = "Dengan menerobos masuk ke Balai Kehakiman, Anda telah mengganggu proses peradilan dan melanggar kesucian Balai tersebut. Ini adalah pelanggaran pertama Anda.",
  ui_story_5063_50630201_5_dialog_content = "Kedua, seperti yang Anda tunjukkan dengan baik, Anda adalah buronan hukum.",
  ui_story_5063_50630201_6_dialog_content = "Atas perintah Hakim Ketua sendiri, kamu kini ditangkap. Keamanan dan ketertiban Lumopolis serta hukumnya harus dijaga!",
  ui_story_5063_50630201_7_dialog_content = "Heh, semua pembicaraan tentang \"keselamatan\" dan \"hukum,\" tapi kamu bahkan tidak memahami setengahnya!",
  ui_story_5063_50630201_8_dialog_content = "Kamu bahkan tidak pernah memikirkan mengapa kamu harus mematuhi perintah-perintah yang disebut-sebut itu...",
  ui_story_5063_50630201_9_dialog_content = "Pada akhirnya, kau hanyalah algojo yang diberi makan oleh kota yang tampaknya bersih ini!",
  ui_story_5063_50630201_10_dialog_content = "Kamu pasti benar-benar gila menghina Kesatria Keadilan seperti ini...!",
  ui_story_5063_50630201_11_dialog_content = "Apa lagi yang bisa kulakukan? Kau takkan mendengarkan juga. Kau bahkan tidak mengenalku, tapi sudah penuh prasangka...",
  ui_story_5063_50630201_12_dialog_content = "Kota ini juga tidak lebih baik. Hmph, padahal dulu aku pernah menjadi bagian darinya...",
  ui_story_5063_50630201_13_dialog_content = "Ketika pisau tidak di lehermu, kau tak akan pernah tahu rasanya terjebak dalam jalan buntu karena prasangka dan kesombongan!",
  ui_story_5063_50630201_14_dialog_content = "Maukah kamu ceritakan padaku apa yang terjadi padamu?",
  ui_story_5063_50630201_15_dialog_content = "Sayang sekali, sudah terlambat sekarang. Heh, lihat, mereka sudah di sini.",
  ui_story_5063_50630201_16_dialog_content = "Perlindungan! Kesetiaan! Kemuliaan!",
  ui_story_5063_50630201_17_dialog_content = "Apakah kamu di sini untuk membantuku menangkap buronan? Jika iya, kamu tepat waktu—",
  ui_story_5063_50630201_18_dialog_content = "Menyerang!",
  ui_story_5063_50630201_19_dialog_content = "*Batuk* K-Kamu ini...?",
  ui_story_5063_50630302_1_dialog_content = "Apa yang terjadi? Kenapa para penjaga itu menghilang saat diserang? Aku sangat bingung...",
  ui_story_5063_50630302_2_dialog_content = "Wanita berjubah hitam itu juga menghilang begitu cepat. Kemana dia bisa pergi?",
  ui_story_5063_50630302_3_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5063_50630302_4_dialog_content = "Argh! M-Maafkan aku!",
  ui_story_5063_50630302_5_dialog_content = "Aku berlari sangat cepat sampai-sampai tidak menyadari kamu di sana... Apakah kamu baik-baik saja?",
  ui_story_5063_50630302_6_dialog_content = "Ugh...",
  ui_story_5063_50630302_7_dialog_content = "A-Aku baik-baik saja. Tolong jangan menyalahkan dirimu sendiri, lady ksatria.",
  ui_story_5063_50630302_8_dialog_content = "Saya juga terburu-buru, dan gagal memperhatikan sekitar saya...",
  ui_story_5063_50630302_9_dialog_content = "Jika ada yang harus meminta maaf, seharusnya itu aku!",
  ui_story_5063_50630302_10_dialog_content = "Tolong jangan. Akulah yang menabrak Anda, bukan sebaliknya.",
  ui_story_5063_50630302_11_dialog_content = "Apakah kamu terluka sama sekali?",
  ui_story_5063_50630302_12_dialog_content = "Kamu sebaiknya diperiksa oleh dokter, hanya untuk berjaga-jaga. Dan saya akan menanggung semua biaya medisnya.",
  ui_story_5063_50630302_13_dialog_content = "Hanya benturan dan jatuh, lady knight... Saya menghargai kebaikan Anda, tetapi mengganggu dokter untuk ini sepertinya agak tidak perlu.",
  ui_story_5063_50630302_14_dialog_content = "Selain itu, Anda memiliki masalah yang lebih mendesak untuk dihadapi, bukan? Saya akan merasa sangat menyesal jika kebodohan saya mengganggu tugas mulia Anda.",
  ui_story_5063_50630302_15_dialog_content = "... Setidaknya biarkan aku membantumu untuk berdiri.",
  ui_story_5063_50630302_16_dialog_content = "Kamu juga menjatuhkan beberapa barang. Kamu yakin sudah mengambil semuanya?",
  ui_story_5063_50630302_17_dialog_content = "Ya, Lady Knight. Tidak ada yang tampaknya hilang.",
  ui_story_5063_50630302_18_dialog_content = "Mengerti. Jika Anda mulai merasa tidak enak badan, silakan datang menemui saya segera. Nama saya Irridon Novek.",
  ui_story_5063_50630302_19_dialog_content = "Oh, sebelum saya lupa, apakah Anda kebetulan melihat seseorang yang mencurigakan berlari melewati sini barusan?",
  ui_story_5063_50630302_20_dialog_content = "Karakter mencurigakan? T-Tidak, saya rasa bukan...",
  ui_story_5063_50630302_21_dialog_content = "Hmm? Maafkan saya, Nona, tapi... apakah ada masalah?",
  ui_story_5063_50630302_22_dialog_content = "Jangan takut. Sebagai sesama lulusan Dawn Academy, mungkin saya bisa membantu.",
  ui_story_5063_50630302_23_dialog_content = "Benarkah? T-Terima kasih Cahaya... Aku masih seorang calon biarawati. Kalian bisa memanggilku <color=#FFB400>Pam</color>.",
  ui_story_5063_50630302_24_dialog_content = "Alasan aku terburu-buru adalah—",
  ui_story_5063_50630302_25_dialog_content = "Kami menemukannya, Lady Nodirri! Dia ada di sini!",
  ui_story_5063_50630302_26_dialog_content = "Itu kamu ya, Pam.",
  ui_story_5063_50630302_27_dialog_content = "Guru kami meminta kami untuk mengambil kembali <color=#FFB400>Dawn Emblem</color> yang ada di tangan Anda. May Bisakah saya memilikinya kembali?",
  ui_story_5063_50630302_28_dialog_content = "Aku... kurasa tidak, tidak.",
  ui_story_5063_50630302_29_dialog_content = "Hah? Itu... Itu bukan keputusan yang bisa kamu buat.",
  ui_story_5063_50630302_30_dialog_content = "Meskipun akademi mempercayakan emblem itu padamu untuk semester ini, sebenarnya itu bukan milikmu. Dawn Emblem dimaksudkan untuk diwariskan antar siswa.",
  ui_story_5063_50630302_31_dialog_content = "Mengingat ini adalah hari terakhir semester, kamu tidak punya pilihan selain mengembalikannya. Jika tidak... Bagaimana saya menjelaskan ini kepada guru kita?",
  ui_story_5063_50630302_32_dialog_content = "Kenapa kamu tidak bisa mengembalikannya saja?",
  ui_story_5063_50630302_33_dialog_content = "Jika kamu sangat menyukainya, dapatkan kembali di semester depan.",
  ui_story_5063_50630302_34_dialog_content = "Setidaknya kamu bisa menjelaskan dirimu pada kami, Pam.",
  ui_story_5063_50630302_35_dialog_content = "Aku tak bisa mengembalikannya... Karena lambangnya telah dicuri.",
  ui_story_5063_50630302_36_dialog_content = "Apa? Tapi bagaimana? Bagaimana kamu bisa membiarkan sesuatu yang begitu berharga dicuri?!",
  ui_story_5063_50630302_37_dialog_content = "Aku…",
  ui_story_5063_50630302_38_dialog_content = "Mengapa kamu bilang itu \"dicuri\"?",
  ui_story_5063_50630302_39_dialog_content = "Apakah kamu mencoba menyembunyikan bahwa kamu kehilangan itu secara tidak sengaja?",
  ui_story_5063_50630302_40_dialog_content = "Atau mungkin Anda ingin menyimpannya untuk diri sendiri! Maksud saya, emblem itu terbuat dari emas murni dan sangat berharga.",
  ui_story_5063_50630302_41_dialog_content = "Tolong tenangkan diri, semua orang. Sebagai Justice Knight, saya juga pernah menjadi siswa di Dawn Academy.",
  ui_story_5063_50630302_42_dialog_content = "Jika Emblem Dawn Pam benar-benar dicuri, maka ini sekarang menjadi masalah kriminal yang layak diselidiki!",
  ui_story_5063_50630302_43_dialog_content = "Tenanglah, Pam, saya tidak akan beristirahat sampai pelakunya ditangkap dan diadili.",
  ui_story_5063_50630302_44_dialog_content = "Sejujurnya, ada seseorang yang saya curigai mencurinya...",
  ui_story_5063_50630302_45_dialog_content = "Dia salah satu teman sekelas ku. Untuk menghindari keributan, aku ingin menghadapinya secara pribadi.",
  ui_story_5063_50630302_46_dialog_content = "Siapa yang tahu jika benar-benar ada orang seperti itu? Bagaimana kita bisa tahu jika kamu tidak hanya mengarang semuanya?",
  ui_story_5063_50630302_47_dialog_content = "Kamu benar... Pam terlihat gugup seperti sedang menyembunyikan sesuatu.",
  ui_story_5063_50630302_48_dialog_content = "Jika ada seseorang yang mencurigakan, cukup bicara saja, dan kita semua akan membantu kamu mendapatkannya kembali.",
  ui_story_5063_50630302_49_dialog_content = "Aku…",
  ui_story_5063_50630302_50_dialog_content = "Jangan takut, Pam. Ceritakan pada kami, dan kami akan mengambil kembali Dawn Emblem dan membuktikan ketidakbersalahanku!",
  ui_story_5063_50630302_51_dialog_content = "Sebenarnya... Aku menemukan sesuatu di dekat tempat emblemku hilang. Itu adalah saputangan milik salah satu teman sekelasku.",
  ui_story_5063_50630302_52_dialog_content = "Hah? Kenapa kau menatapku?",
  ui_story_5063_50630302_53_dialog_content = "Karena saputangan ini milikmu, Nodirri.",
  ui_story_5063_50630302_54_dialog_content = "Apakah kamu menuduh saya melakukan sesuatu?",
  ui_story_5063_50630302_55_dialog_content = "Sebenarnya aku kehilangan saputangan itu beberapa hari yang lalu... Lagipula, bukan berarti aku belum pernah punya emblem itu sebelumnya!",
  ui_story_5063_50630302_56_dialog_content = "Hanya orang miskin yang akan menemukan nilai dalam mencuri emblem emas padat seperti itu.",
  ui_story_5063_50630302_57_dialog_content = "Sebagai bangsawan Lumopolis, mengapa aku harus merendahkan diri melakukan hal memalukan seperti pencurian? Keluargaku sudah memiliki kekayaan yang lebih dari cukup.",
  ui_story_5063_50630302_58_dialog_content = "Aku juga merasa aneh, tapi...",
  ui_story_5063_50630302_59_dialog_content = "Apa mungkin aku salah?",
  ui_story_5063_50630302_60_dialog_content = "Pam... Aku tidak pernah menyangka kamu tipe penjahat seperti ini. Kamu jelas mencoba mengalihkan kesalahan dari dirimu sendiri, 'kan?",
  ui_story_5063_50630302_61_dialog_content = "Aku tidak! Demi White Night, aku bersumpah bahwa setiap kata yang telah aku ucapkan adalah kebenaran. Jika aku berbohong, maka semoga Dewa Cahaya menghukumku di tempat aku berdiri!",
  ui_story_5063_50630302_62_dialog_content = "Apakah kamu kebetulan ingat apa yang terjadi sebelum dan sesudah lambangmu hilang?",
  ui_story_5063_50630302_63_dialog_content = "Ya, aku berada di ruang belajar mandiri saat melepaskannya dari gaunku. Aku berencana mengembalikannya ke guru ku.",
  ui_story_5063_50630302_64_dialog_content = "Tapi tiba-tiba, aku mendengar suara anak kucing menangis kesakitan dari luar jendela. Aku pergi dan mencari ke mana-mana, tapi aku tidak bisa menemukannya.",
  ui_story_5063_50630302_65_dialog_content = "Ketika aku kembali ke ruangan, Dawn Emblemku telah menghilang. Satu-satunya yang aku temukan hanyalah sapu tangan itu...",
  ui_story_5063_50630302_66_dialog_content = "Oh, begitu. Kalau begitu, serahkan penyelidikannya kepadaku.",
  ui_story_5063_50630303_1_dialog_content = "<color=#e8d9bb>Di atas rumput hijau Dawn Academy, sesuatu berkilauan terang.</color>",
  ui_story_5063_50630303_2_dialog_content = "<color=#e8d9bb>Irridon dengan hati-hati menyibakkan semak hijau dan menemukan bulu pena berlapis emas.</color>",
  ui_story_5063_50630303_3_dialog_content = "<color=#FFB400>Sebatang pena</color>?",
  ui_story_5063_50630303_4_dialog_content = "Ini dari saat itu...",
  ui_story_5063_50630303_5_dialog_content = "Jadi, apa yang diinginkan oleh Irridon yang tinggi dan agung dengan Anda barusan?",
  ui_story_5063_50630303_6_dialog_content = "Dia bilang dia melihat saya dalam kesulitan tanpa pena, jadi dia meminjamkan pena bulu berlapis emasnya kepada saya.",
  ui_story_5063_50630303_7_dialog_content = "Ini hanya bulu pena berlapis emas, dan semua orang punya. Apa yang bisa dibanggakan?",
  ui_story_5063_50630303_8_dialog_content = "Tepat sekali. Dan ingat bagaimana dia berjalan dengan wajah acuh tak acuh, berlagak seperti dia sangat sombong dan angkuh?",
  ui_story_5063_50630303_9_dialog_content = "Dia hanya mendapatkan nilai ini karena <color=#FFB400>ayahnya</color>. Ngomong-ngomong, kamu tidak merasa jijik menggunakan barang-barangnya?",
  ui_story_5063_50630303_10_dialog_content = "Makanya aku membuangnya sudah lama...",
  ui_story_5063_50630303_11_dialog_content = "Bagus sekali.",
  ui_story_5063_50630303_12_dialog_content = "Tak pernah kuduga aku akan menemukannya lagi setelah bertahun-tahun.",
  ui_story_5063_50630303_13_dialog_content = "Tunggu... Apa sudah selama itu? Kenapa aku tidak bisa mengingatnya?",
  ui_story_5063_50630303_14_dialog_content = "Mungkin lebih baik jika aku melupakan saja.",
  ui_story_5063_50630304_1_dialog_content = "Hmm? Laporan nilai ini hampir sempurna... Ini adalah pemandangan yang jarang, bahkan di Dawn Academy.",
  ui_story_5063_50630304_2_dialog_content = "Siapa yang bisa melupakan sesuatu yang begitu penting di halaman akademi? Aku hampir tidak bisa membaca namanya...",
  ui_story_5063_50630304_3_dialog_content = "\"<color=#FFB400>Irridon Novek</color>\"? Tunggu... Ini milikku!",
  ui_story_5063_50630304_4_dialog_content = "...",
  ui_story_5063_50630304_5_dialog_content = "Awalnya, saya pikir ini akan membuat ayah saya bahagia.",
  ui_story_5063_50630304_6_dialog_content = "Tapi saat aku menunjukkannya kepadanya, ekspresi wajahnya sama sekali tidak berubah.",
  ui_story_5063_50630304_7_dialog_content = "Baginya, ini adalah sesuatu yang seharusnya bisa aku selesaikan. Dia bilang jangan buang-buang waktunya.",
  ui_story_5063_50630304_8_dialog_content = "Aku sudah siap untuk tanggapan seperti itu... Tapi hari itu, dia meninggalkan pekerjaannya hanya untuk mengkritikku.",
  ui_story_5063_50630304_9_dialog_content = "Dia bertanya padaku mengapa aku tidak memiliki teman di Dawn Academy, dan mengapa aku tidak menjaga hubungan yang lebih baik dengan teman sebayaku.",
  ui_story_5063_50630304_10_dialog_content = "Ayahku percaya bahwa aku tidak berusaha sebaik mungkin, dan tindakanku akan mencoreng nama baik keluarga kami. Dia khawatir pekerjaannya akan terpengaruh...",
  ui_story_5063_50630304_11_dialog_content = "Aku tidak tahu harus berkata apa. Yang bisa kulakukan hanyalah menundukkan kepala dalam rasa malu.",
  ui_story_5063_50630304_12_dialog_content = "\"Tak berguna!\" ... Untuk waktu yang lama setelah itu, inilah cara paling umum ayahku menyapa saya.",
  ui_story_5063_50630304_13_dialog_content = "Apakah aku benar-benar tidak berguna...?",
  ui_story_5063_50630304_14_dialog_content = "Apakah aku tidak mencoba yang terbaik...?",
  ui_story_5063_50630601_1_dialog_content = "Bagaimana penyelidikannya, Justice Knight?",
  ui_story_5063_50630601_2_dialog_content = "Sepertinya kamu rekrutan baru... Aku tidak suka menekanmu seperti ini, tapi waktunya semakin menipis.",
  ui_story_5063_50630601_3_dialog_content = "Mungkin sebaiknya aku melaporkan ini kepada guru-guru kita, dan biarkan akademi yang menangani masalah ini?",
  ui_story_5063_50630601_4_dialog_content = "Tidak perlu. Saya sudah membuat kemajuan yang cukup, tetapi saya masih memiliki satu pertanyaan terakhir untuk Anda. Katakan padaku, kapan tepatnya kamu kehilangan sapu tanganmu?",
  ui_story_5063_50630601_5_dialog_content = "Bukankah aku sudah menjawab pertanyaan itu? Aku sudah bilang sebelumnya, aku kehilangan itu beberapa hari lalu.",
  ui_story_5063_50630601_6_dialog_content = "Penjaga akademi melihat Anda membuka pintu ruang belajar mandiri dengan sapu tangan Anda sebelumnya. Bisakah Anda menjelaskan?",
  ui_story_5063_50630601_7_dialog_content = "Kupikir dia tertidur sepanjang waktu itu...",
  ui_story_5063_50630601_8_dialog_content = "Jadi kamu mengakui bahwa kamu masuk ke ruang belajar mandiri lebih awal hari ini?",
  ui_story_5063_50630601_9_dialog_content = "Tunggu... Aku mencium adanya permainan kotor. Kau memihak Pam sejak awal, bukan? Katakan padaku, apa jenis kesepakatan yang kau buat dengannya?",
  ui_story_5063_50630601_10_dialog_content = "Kau bahkan tidak repot-repot mencari barang yang hilang padanya saat semua orang ada di sana!",
  ui_story_5063_50630601_11_dialog_content = "Tapi aku... Aku hanya meminta bantuan ksatria wanita itu karena aku tidak bisa menemukan Emblem Dawn ku!",
  ui_story_5063_50630601_12_dialog_content = "Kamu bilang begitu, tapi bagaimana kami tahu kamu tidak berbohong?",
  ui_story_5063_50630601_13_dialog_content = "A-Aku tidak menyembunyikan apa pun! Geledah aku, jika kamu harus!",
  ui_story_5063_50630601_14_dialog_content = "Baiklah.",
  ui_story_5063_50630601_15_dialog_content = "Semuanya, untuk berjaga-jaga, mari kita lanjutkan dan mencari.",
  ui_story_5063_50630601_16_dialog_content = "Dan jangan lupa tentang tas Pam!",
  ui_story_5063_50630601_17_dialog_content = "Aku menemukan sesuatu... Apa ini?!",
  ui_story_5063_50630601_18_dialog_content = "Emblem Dawn?",
  ui_story_5063_50630601_19_dialog_content = "Jadi, selama ini ada di dirimu!",
  ui_story_5063_50630601_20_dialog_content = "Kamu pembohong tak tahu malu... Apakah lambang ini benar-benar sangat berarti bagimu?",
  ui_story_5063_50630601_21_dialog_content = "T-Tidak... Bagaimana ini bisa terjadi? Itu tidak ada di tas ku saat aku mencarinya...",
  ui_story_5063_50630601_22_dialog_content = "Apa yang membuatmu melakukan hal seperti itu? Ceritakan kepada kami, dan mungkin kami bersedia untuk memahaminya.",
  ui_story_5063_50630601_23_dialog_content = "Presiden Nodirri, jangan bersimpati padanya. Dia sudah melanggar hukum di Lumopolis!",
  ui_story_5063_50630601_24_dialog_content = "Ksatria Keadilan, apa yang kamu tunggu? Tangkap dia sekarang juga!",
  ui_story_5063_50630601_25_dialog_content = "Kasus ini masih dalam penyelidikan.",
  ui_story_5063_50630601_26_dialog_content = "Apa?",
  ui_story_5063_50630601_27_dialog_content = "Emblem Dawn ini bukanlah terbuat dari emas murni... Bahkan, sepertinya ini adalah <color=#FFB400>palsu</color>.",
  ui_story_5063_50630601_28_dialog_content = "Lady Irridon... Ini sama sekali bukan palsu. Saya bisa meyakinkan Anda, ini adalah lambang yang saya hilangkan.",
  ui_story_5063_50630601_29_dialog_content = "Jangan berpikir kami tidak bisa melihat melalui sandiwaramu! Kamu menanamkan barang palsu ini di tas kamu agar bisa menyimpan yang asli tersembunyi, bukan?!",
  ui_story_5063_50630601_30_dialog_content = "Kamu salah! Emblem emas itu sangat berharga sehingga aku khawatir tidak bisa menjaganya dengan baik...",
  ui_story_5063_50630601_31_dialog_content = "Jadi, saya meminta Emblem Dawn yang berbeda dari Akademi, yang tidak terbuat dari emas asli.",
  ui_story_5063_50630601_32_dialog_content = "Aku tahu emblem ini hampir tidak ada harganya, tetapi kehormatan yang diberikannya kepada ku lebih dari cukup.",
  ui_story_5063_50630601_33_dialog_content = "Sekarang kamu hanya membuat-buat! Aku belum pernah dengar Dawn Academy memberikan lambang palsu kepada para siswanya!",
  ui_story_5063_50630601_34_dialog_content = "Tapi aku tidak! Tanya saja pada guru kita... Kamu akan melihat bahwa aku mengatakan yang sebenarnya jika kamu melakukannya!",
  ui_story_5063_50630601_35_dialog_content = "Jika lambang ini benar-benar tidak memiliki nilai moneter, maka Pam tidak memiliki alasan untuk mencurinya.",
  ui_story_5063_50630601_36_dialog_content = "Presiden Nodirri, bagaimana kalau kita tanya guru cara menangani ini?",
  ui_story_5063_50630601_37_dialog_content = "Cukup, kalian semua!",
  ui_story_5063_50630601_38_dialog_content = "Jika bukan karena uang, hanya ada satu kemungkinan... Fitnah! Dia mencoba menodai reputasiku sejak awal!",
  ui_story_5063_50630601_39_dialog_content = "Tanpa saya di sini, Pam pasti tidak akan kesulitan mendapatkan tempat di Lumopolis Temple sebagai calon biarawati! Benar kan?!",
  ui_story_5063_50630601_40_dialog_content = "I-Itu sama sekali bukan itu...!",
  ui_story_5063_50630601_41_dialog_content = "Kamu bodoh melakukan ini, Pam. Tindakanmu hanya membuatmu semakin jauh dari kuil dan kemuliaannya.",
  ui_story_5063_50630601_42_dialog_content = "Lagipula, seseorang dengan status rendah seperti dirimu tidak memiliki hak untuk naik ke Kuil Lumopolis!",
  ui_story_5063_50630601_43_dialog_content = "Dan bahkan jika kamu berhasil masuk, bangsawan lain dan anak-anak mereka akan menginjak-injakmu hingga hancur! Apakah kamu benar-benar tidak tahu apa-apa?!",
  ui_story_5063_50630601_44_dialog_content = "Ada yang tidak beres. Ketika aku tanpa sengaja menabrak Pam sebelumnya, isi tasnya berserakan di tanah.",
  ui_story_5063_50630601_45_dialog_content = "Aku tidak ingat melihat emblem ini di antara barang-barang yang jatuh dari miliknya, jadi bagaimana bisa muncul begitu saja?",
  ui_story_5063_50630601_46_dialog_content = "Kecuali... seseorang memasukkannya ke dalam tas ku setelah pertemuan kita?",
  ui_story_5063_50630601_47_dialog_content = "Bermain trik kekanak-kanakan pada orang lain itu satu hal, tapi melibatkan seorang Ksatria Keadilan dari Lumopolis dalam masalah ini? Apakah mereka tidak tahu malu?!",
  ui_story_5063_50630601_48_dialog_content = "Siapa pun yang bertanggung jawab atas ini harus segera mengaku, jika tidak, saya tidak akan memberi keringanan.",
  ui_story_5063_50630601_49_dialog_content = "Wanita Irridon!",
  ui_story_5063_50630601_50_dialog_content = "Emblem Dawn ku kembali dalam kepemilikanku, dan sepertinya tidak rusak sama sekali. Itu lebih dari cukup untuk membuat pikiranku tenang.",
  ui_story_5063_50630601_51_dialog_content = "Itu semua baik-baik saja, tetapi masalahnya kini menjadi lebih rumit dari itu.",
  ui_story_5063_50630601_52_dialog_content = "Tapi... Tapi mungkin saja aku tidak menyadarinya tadi, bukan?",
  ui_story_5063_50630601_53_dialog_content = "Hmph, sepertinya memang begitu. Kamu harus lebih berhati-hati lain kali, agar tidak membuang waktu semua orang dengan ulah kekanak-kanakanmu lagi. Ayo, semua!",
  ui_story_5063_50630601_54_dialog_content = "Yah? Kamu datang atau tidak?!",
  ui_story_5063_50630601_55_dialog_content = "Siap, Presiden Nodirri.",
  ui_story_5063_50630601_56_dialog_content = "Mengapa kamu memilih untuk membiarkan dia pergi, Pam? Jelas dia adalah pelakunya!",
  ui_story_5063_50630601_57_dialog_content = "Karena dia tidak melakukan sesuatu yang benar-benar keji... Itu hanya kehilangan hati nurani sesaat, tidak lebih. Selain itu, saya yakin hatinya sudah penuh dengan rasa bersalah dan penyesalan.",
  ui_story_5063_50630601_58_dialog_content = "Dewa Cahaya mengajarkan kita untuk saling memaafkan. Sebagai calon biarawati, saya tidak memiliki hak untuk melawan ajaran kami.",
  ui_story_5063_50630601_59_dialog_content = "Saya percaya Dewa Cahaya akan membimbing langkahnya dan membantu dia menjadi orang yang lebih baik... Malam Putih di atas.",
  ui_story_5063_50630601_60_dialog_content = "Benarkah? Heh, baiklah. Bahkan jika insiden ini tidak pernah terjadi, saya yakin bahwa Lumopolis Temple pasti akan memilihmu untuk tinggal.",
  ui_story_5063_50630601_61_dialog_content = "Hah? Mereka masih belum membuat keputusan, lho...",
  ui_story_5063_50630601_62_dialog_content = "Aku hanya berharap punya teman sekelas seperti kamu saat masih di Akademi. Mungkin kita... Bisa jadi teman.",
  ui_story_5063_50630601_63_dialog_content = "Tapi kamu adalah ksatria yang gagah dan berbakti, Lady Irridon! Saya yakin kamu memiliki banyak teman di Akademi!",
  ui_story_5063_50630601_64_dialog_content = "Sebenarnya, justru sebaliknya. Semua orang berpikir bahwa pencapaian saya hanyalah hasil dari menjadi putri ayah saya. Mengatakan bahwa saya dibenci oleh teman sebaya saya adalah suatu pemahaman yang kurang.",
  ui_story_5063_50630601_65_dialog_content = "Bahkan ayahku mulai percaya pada rumor yang mereka sebarkan tentangku. Itu... Masa yang sangat kesepian di masa lalu.",
  ui_story_5063_50630601_66_dialog_content = "Kalau begitu, mari kita berteman sekarang!",
  ui_story_5063_50630601_67_dialog_content = "Kita mungkin bukan teman sekelas, tetapi kita masih bisa menjadi teman baik! Pertemuan kita pasti sudah direncanakan dengan sempurna oleh takdir!",
  ui_story_5063_50630601_68_dialog_content = "Direncanakan... Oleh takdir?",
  ui_story_5063_50630601_69_dialog_content = "Tentu saja! Siapa lagi yang bisa menyelamatkan saya selain Lady Irridon dari Justice Knights?",
  ui_story_5063_50630601_70_dialog_content = "Y-Yah, ada banyak ksatria lain—",
  ui_story_5063_50630601_71_dialog_content = "Mengakui bakat dan nilai diri sendiri bukanlah kejahatan, Lady Irridon. Apakah kamu setuju?",
  ui_story_5063_50630601_72_dialog_content = "Hah? T-Tidak, kurasa itu tidak melanggar hukum...",
  ui_story_5063_50630601_73_dialog_content = "Sekarang setelah saya pikirkan, saya percaya Pittman juga ingin menjadi Kesatria Keadilan!",
  ui_story_5063_50630601_74_dialog_content = "<color=#FFB400>Pittman</color>? Nama itu terdengar agak familiar...",
  ui_story_5063_50630601_75_dialog_content = "Dia salah satu teman saya. Dia pasti akan sangat senang bertemu dengan Ksatria Keadilan yang luar biasa seperti dirimu, tahu!",
  ui_story_5063_50630601_76_dialog_content = "Kamu pikir aku... Luar biasa?",
  ui_story_5063_50630601_77_dialog_content = "Tentu saja! Aku akan pastikan memperkenalkan kalian berdua suatu hari nanti.",
  ui_story_5063_50630601_78_dialog_content = "Astaga, lihat jamnya! Aku masih perlu menjenguk kakekku di rumahnya...",
  ui_story_5063_50630601_79_dialog_content = "Maafkan saya, Nona Irridon, tapi saya harus pergi sekarang!",
  ui_story_5063_50630601_80_dialog_content = "Pertemuan berikutnya, aku berjanji akan membalas semua kebaikanmu dengan benar!",
  ui_story_5063_50630701_1_dialog_content = "Apakah aku... Benar-benar seorang Ksatria Keadilan yang luar biasa?",
  ui_story_5063_50630701_2_dialog_content = "Apa jenis Knight of Justice yang membiarkan penjahat pergi begitu saja...",
  ui_story_5063_50630701_3_dialog_content = "Haruskah saya melaporkan ini kepada Hakim Ketua?",
  ui_story_5063_50630701_4_dialog_content = "Pergi dan tangkap wanita gila itu! Jangan mengecewakanku lagi!",
  ui_story_5063_50630701_5_dialog_content = "Aku hanya akan mengecewakannya lebih dari yang sudah aku lakukan...",
  ui_story_5063_50630701_6_dialog_content = "Mungkin dia menganggap aku tidak berguna, sama seperti ayahku.",
  ui_story_5063_50630701_7_dialog_content = "Sebenarnya... Mereka mungkin akan mengusir saya dari Hall of Justice karena ini...",
  ui_story_5063_50630701_8_dialog_content = "...",
  ui_story_5063_50630701_9_dialog_content = "Hah? Itu dia!!",
  ui_story_5063_50630701_10_dialog_content = "Dia mencoba melarikan diri ke Halaman Lumopolis melalui Stairway to the Skies...",
  ui_story_5063_50630701_11_dialog_content = "Bagus, setidaknya Lumopolis Gardens aman dari tindakannya!",
  ui_story_5063_50630701_12_dialog_content = "Tunggu, itu bukan alasan untuk lega! Aku harus mengejarnya!",
  ui_story_5063_50630701_13_dialog_content = "Perlindungan! Kesetiaan! Kemuliaan!",
  ui_story_5063_50630701_14_dialog_content = "Prajurit aneh itu kembali lagi!",
  ui_story_5063_50630701_15_dialog_content = "Tolong menjauhlah dariku! Kamu menghalangi pengejaranku terhadap penjahat!",
  ui_story_5063_50630802_1_dialog_content = "Berhenti-!",
  ui_story_5063_50630802_2_dialog_content = "Dia menghilang lagi? Saya harus menanyakan kepada orang-orang di depan apakah mereka melihatnya.",
  ui_story_5063_50630802_3_dialog_content = "Kita selalu bisa pergi ke Hall of Justice, jika perlu!",
  ui_story_5063_50630802_4_dialog_content = "Aku juga berpikir begitu. Aku bersumpah akan menyelesaikan masalah ini!",
  ui_story_5063_50630802_5_dialog_content = "Maaf, Pak, tapi apakah salah satu dari Anda melihat seorang wanita mencurigakan berpakaian hitam berlari di area ini?",
  ui_story_5063_50630802_6_dialog_content = "Saya belum melihat wanita berpakaian hitam, tetapi pria di depan kita, Jerry, terlihat sangat mencurigakan bagi saya.",
  ui_story_5063_50630802_7_dialog_content = "Inilah kesempatan Anda, Tuan Major! Silakan, bagikan pikiran Anda dengan Balai Kehakiman!",
  ui_story_5063_50630802_8_dialog_content = "Menegur orang tak bersalah di jalanan, hanya untuk menginterogasi mereka secara membabi buta... Apakah ini juga bagian dari didikan bangsawan?!",
  ui_story_5063_50630802_9_dialog_content = "Tahu tempatmu, pelayan! Didikan bangsawan sama sekali tidak menyangkut orang desa rendahan seperti dirimu!",
  ui_story_5063_50630802_10_dialog_content = "Gangguan publik merupakan pelanggaran langsung terhadap hukum Lumopolis. Saya sarankan kalian berdua tenang sekarang juga.",
  ui_story_5063_50630802_11_dialog_content = "Sekarang apa yang menjadi masalahnya? Saya dengan senang hati akan menjadi mediator.",
  ui_story_5063_50630802_12_dialog_content = "Anda seorang Ksatria Keadilan, bukan? Mohon maafkan luapan emosi saya barusan.",
  ui_story_5063_50630802_13_dialog_content = "Kamu datang pada saat yang tepat. Saya ingin melaporkan pelayan yang rakus dan tidak tahu malu ini! Kamu akan membantu saya, kan?",
  ui_story_5063_50630802_14_dialog_content = "Lagi, tolong tenangkan diri dan ceritakan dengan tepat apa yang terjadi.",
  ui_story_5063_50630802_15_dialog_content = "Hari ini, ayah yang sudah tua saya tiba-tiba dan <color=#FFB400>secara misterius meninggal dunia</color>.",
  ui_story_5063_50630802_16_dialog_content = "Saya datang untuk mengurus harta warisannya segera setelah saya menerima kabar tersebut, tetapi pria ini— seorang pelayan yang bekerja untuk ayah saya bernama Jerry— menolak untuk membiarkan saya masuk ke tempat tersebut.",
  ui_story_5063_50630802_17_dialog_content = "Dia memberikan saya <color=#FFB400>surat wasiat</color> yang aneh ini, mengatakan bahwa ayah saya mewariskan gelar dan harta bendanya sepenuhnya kepada dia.",
  ui_story_5063_50630802_18_dialog_content = "Gagasan seorang ayah yang mencabut nama dan status keluarga dari anaknya sendiri...",
  ui_story_5063_50630802_19_dialog_content = "J-Jika ini benar, keluarga kita akan menjadi orang biasa saja!",
  ui_story_5063_50630802_20_dialog_content = "Ini benar-benar tidak masuk akal, bukan? Sebagai seorang ksatria, saya yakin kamu setuju!",
  ui_story_5063_50630802_21_dialog_content = "Kecuali ada permainan kotor, memang sangat jarang bagi seorang bangsawan untuk melepaskan seluruh warisannya, terutama kepada...",
  ui_story_5063_50630802_22_dialog_content = "Untuk seorang pelayan rendahan? Itu yang ingin Anda katakan, bukan?",
  ui_story_5063_50630802_23_dialog_content = "Benarkah saya berasumsi bahwa Anda terlahir dalam kehidupan kekayaan dan bangsawan, lady knight? Kehidupan di mana semua keinginan dan kebutuhan Anda terpenuhi hanya dengan sekali jentikan jari?",
  ui_story_5063_50630802_24_dialog_content = "Terlepas dari latar belakang saya, saya adalah Justice Knight dari Lumopolis, dan saya memiliki kewajiban untuk memperlakukan kedua belah pihak secara adil dan setara.",
  ui_story_5063_50630802_25_dialog_content = "Sekarang tolong, ceritakan versi Anda tentang masalah ini.",
  ui_story_5063_50630802_26_dialog_content = "Meskipun benar bahwa Lord Major adalah anak dari tuanku, keduanya selalu bertentangan satu sama lain, dan Lord Major jarang mengunjungi tuanku saat ia masih hidup.",
  ui_story_5063_50630802_27_dialog_content = "Hingga saat dia menghembuskan nafas terakhir, aku lah yang merawat tuanku, siang dan malam.",
  ui_story_5063_50630802_28_dialog_content = "Meskipun latar belakang saya sederhana, guru saya selalu mendorong saya untuk terus berkembang. Akhirnya, dia mulai menganggap saya seperti anak kandungnya sendiri.",
  ui_story_5063_50630802_29_dialog_content = "Dia menyusun surat wasiat ini untuk membuktikan keikhlasannya dan meredakan keraguan saya. Anda akan menemukan bahwa ini sepenuhnya sesuai dengan hukum Lumopolis...",
  ui_story_5063_50630802_30_dialog_content = "Aku hanya mengatakan yang sebenarnya! Jika ada yang kukatakan adalah bohong, biarlah aku diturunkan oleh God of Light!",
  ui_story_5063_50630802_31_dialog_content = "Jangan tertipu oleh bahasa bunganya, ksatria wanita. Dewa Cahaya tidak akan pernah mendengarkan satu kata pun dari mulut pembohongnya.",
  ui_story_5063_50630802_32_dialog_content = "Mengenai kunjungan yang jarang, ayahku memberiku sedikit pilihan. Pria itu hanya menolak untuk bertemu denganku.",
  ui_story_5063_50630802_33_dialog_content = "Dan sebelum kamu mulai mencurigai apa pun, aku tidak pernah bersalah pada ayahku dengan cara apa pun. Dia selalu sangat ketat dengan saya, dan ekspektasinya selalu begitu tinggi...",
  ui_story_5063_50630802_34_dialog_content = "Di matanya, saya hanyalah seorang anak yang malas, bodoh, dan puas dengan diri sendiri.",
  ui_story_5063_50630802_35_dialog_content = "Meskipun saya telah berusaha keras untuk memenuhi tuntutannya, dia tidak pernah merasa puas. Tidak satupun kali dia mengakui saya sebagai orang yang berharga.",
  ui_story_5063_50630802_36_dialog_content = "Terlepas dari ketidakpuasannya terhadap saya, saya tahu ayahku tidak akan pernah meninggalkan surat wasiat seperti ini.",
  ui_story_5063_50630802_37_dialog_content = "Dan itu karena dia sangat menyayangi cucunya, putri saya sendiri.",
  ui_story_5063_50630802_38_dialog_content = "Dia sering mengunjunginya untuk menemani dan memastikan dia baik-baik saja. Menolak saya adalah satu hal, tetapi dia tidak akan pernah mencabut hak waris cucunya yang sah!",
  ui_story_5063_50630802_39_dialog_content = "Apakah kamu juga kenal dengan cucu perempuan tuanmu, Jerry?",
  ui_story_5063_50630802_40_dialog_content = "Ya. Saya juga penasaran mengapa tuanku tidak meninggalkan kekayaannya untuknya, tetapi dia bilang dia tidak terlalu membutuhkannya.",
  ui_story_5063_50630802_41_dialog_content = "Hahahaha! Betapa sangat konyol! Saya berani bilang, saya belum pernah mendengar kebohongan yang lebih menyedihkan dalam hidup saya!",
  ui_story_5063_50630802_42_dialog_content = "Ayo mengaku saja! Ini semua hanyalah skema jahat untuk merampok mata pencaharian kita!",
  ui_story_5063_50630802_43_dialog_content = "Lord Major, seharusnya kau tahu bahwa aku bukan orang yang termotivasi oleh kekayaan. Jika memang begitu, aku tidak akan pernah setia di sisi ayahmu selama ini.",
  ui_story_5063_50630802_44_dialog_content = "Namun demikian, tuan saya telah menjelaskan dengan sangat jelas bahwa ini adalah keinginan terakhirnya, dan saya tidak berniat untuk mengabaikan mereka!",
  ui_story_5063_50630802_45_dialog_content = "(Aku merasa seolah pernah melihat dilema serupa sebelumnya. Apakah itu kasus dari masa akademi ku?)",
  ui_story_5063_50630802_46_dialog_content = "(Aku masih tidak bisa mengingat... Ugh, kenapa aku merasa sangat pusing?)",
  ui_story_5063_50630802_47_dialog_content = "Wanita Irridon?",
  ui_story_5063_50630802_48_dialog_content = "Ayah, Jerry... Apa yang kalian semua lakukan di sini? Apakah kalian semua saling kenal satu sama lain?",
  ui_story_5063_50630802_49_dialog_content = "Kamu kenal ksatria ini, Pam?",
  ui_story_5063_50630802_50_dialog_content = "Ya, Ayah. Wanita Irridon adalah teman saya yang baru-baru ini membantu saya dengan masalah. Bahkan, saya sedang mempertimbangkan untuk mengundangnya makan malam...",
  ui_story_5063_50630802_51_dialog_content = "Itu tidak akan jadi masalah, kan Ayah? Toh, kalian berdua sepertinya sudah saling mengenal.",
  ui_story_5063_50630802_52_dialog_content = "Sekarang jika semua orang bisa memaafkan saya, saya khawatir tentang kakek saya. Tidak ada yang menjawab pintu saat saya mengunjunginya tadi... Apakah ada yang tahu mengapa?",
  ui_story_5063_50630802_53_dialog_content = "Pam, kakekmu... Sudah tidak bersama kita lagi.",
  ui_story_5063_50630802_54_dialog_content = "<size=45>D-Dia meninggal?!</size>",
  ui_story_5063_50630802_55_dialog_content = "Tapi kakek selalu sehat! Bagaimana ini bisa terjadi?! Aku tidak percaya! Ini pasti hanya lelucon!",
  ui_story_5063_50630802_56_dialog_content = "Dia belum melihat penerimaan resmiku ke dalam Kuil Lumopolis, bagaimana dia bisa meninggalkanku begitu saja?",
  ui_story_5063_50630802_57_dialog_content = "Ayah? Jerry? Kenapa wajah kalian seperti itu? Tolong... Katakan ini tidak nyata...",
  ui_story_5063_50630802_58_dialog_content = "(Saya tidak bisa mengabaikan kasus ini, terlebih karena sangat mempengaruhi Pam.)",
  ui_story_5063_50630802_59_dialog_content = "Semua, tolong terima belasungkawa saya yang paling tulus...",
  ui_story_5063_50630802_60_dialog_content = "Izinkan saya untuk menangani penyelidikan masalah ini secara pribadi.",
  ui_story_5063_50630803_1_dialog_content = "<color=#e8d9bb>Selama penyelidikan Irridon di rumah Kakek Pam, ia secara tak terduga menemukan sebuah tongkat penunjuk tersembunyi di sudut, tampaknya tidak mencolok.</color>",
  ui_story_5063_50630803_2_dialog_content = "Sebuah <color=#FFB400>batang penunjuk</color>...",
  ui_story_5063_50630803_3_dialog_content = "Ini persis sama dengan milik ayahku!",
  ui_story_5063_50630803_4_dialog_content = "Tanganku masih ingat rasa sakit dari setiap kesalahan yang pernah kubuat.",
  ui_story_5063_50630803_5_dialog_content = "Rasa sakit yang dingin, keras, dan menusuk itu...",
  ui_story_5063_50630803_6_dialog_content = "Hanya melihat salah satu tongkat penunjuk ini saja sudah cukup membuat jantungku berdebar kencang.",
  ui_story_5063_50630803_7_dialog_content = "Tiba-tiba, saya teringat adegan mengerikan itu: ayah berdiri di hadapan saya, dengan cakar Eclipsite menancap dalam di dada ayah...",
  ui_story_5063_50630803_8_dialog_content = "Ayahku tidak pernah peduli padaku, jadi mengapa dia mengorbankan hidupnya untuk anak perempuannya yang \"tak berguna\"?",
  ui_story_5063_50630803_9_dialog_content = "Aku masih belum mengerti. Itulah mengapa, bahkan sekarang, aku masih terlalu takut untuk berjalan melewati ruang kerjanya...",
  ui_story_5063_50630803_10_dialog_content = "Setelah aku berhenti menjadi tidak berguna, dan menjadi Kesatria Keadilan yang layak di mata Hakim Agung... Akankah aku memiliki keberanian untuk menghadapi ayahku saat itu?",
  ui_story_5063_50630803_11_dialog_content = "Ayah Pam, Lord Major, tampaknya memiliki sejarah yang mirip dengan ayahnya sendiri.",
  ui_story_5063_50630803_12_dialog_content = "Tapi demi putrinya, dia berhasil mengakhiri siklus jahat ini di masanya sendiri. Saya yakin itu tidak mudah baginya.",
  ui_story_5063_50630803_13_dialog_content = "Tuan Major... Kamu telah melakukannya dengan baik.",
  ui_story_5063_50630803_14_dialog_content = "Kalau aku... Aku juga perlu melakukan hal yang sama.",
  ui_story_5063_50630804_1_dialog_content = "Apakah itu berkas kasus resmi yang tergeletak di pinggir jalan? Orang ceroboh macam apa yang bisa...",
  ui_story_5063_50630804_2_dialog_content = "Tunggu! Apakah ini berkas kasus untuk penyelidikan saya saat ini?!",
  ui_story_5063_50630804_3_dialog_content = "Tampaknya hakim yang memimpin kasus ini menemukan bahwa wasiat tersebut memiliki sifat yang meragukan...",
  ui_story_5063_50630804_4_dialog_content = "Alasannya... Saksi yang hadir saat penandatanganan surat wasiat adalah seorang pelayan, bukan notaris resmi. Oleh karena itu, kesaksian saksi tidak dapat diterima secara hukum.",
  ui_story_5063_50630804_5_dialog_content = "Dengan wasiat yang menjadi tidak valid, pembagian harta si almarhum jatuh ke dalam yurisdiksi hukum waris umum kita.",
  ui_story_5063_50630804_6_dialog_content = "Tapi bagaimana bisa begitu? Saya perlu menemukan hakim yang mengawasi kasus ini dan menegur mereka tentang hal ini!",
  ui_story_5063_50630804_7_dialog_content = "Ada tanda tangan di bagian bawah...",
  ui_story_5063_50630804_8_dialog_content = "\"<color=#FFB400>Rodell Novek</color>\"?!",
  ui_story_5063_50630804_9_dialog_content = "Ayahku <color=#FFB400>memimpin</color> kasus ini?!",
  ui_story_5063_50630804_10_dialog_content = "Apakah itu berarti saya harus memberikan keputusan yang sama dengannya...?",
  ui_story_5063_50630804_11_dialog_content = "Apakah ini benar-benar satu-satunya cara untuk mendapatkan penerimaannya? Dengan menerima dan mematuhi setiap katanya?",
  ui_story_5063_50630804_12_dialog_content = "Entah kenapa...",
  ui_story_5063_50630804_13_dialog_content = "Entah mengapa, saya merasa keputusan ini tidak tepat...",
  ui_story_5063_50631101_1_dialog_content = "(Meskipun alasan-alasannya masih belum jelas, sepertinya kakek Pam memang benar-benar mengakhiri hidupnya sendiri. Titik perdebatan, lalu, berpusat pada wasiatnya.)",
  ui_story_5063_50631101_2_dialog_content = "(Dalam bentuk dan konten, wasiat ini ditulis sesuai dengan hukum waris Lumopolis secara sempurna.)",
  ui_story_5063_50631101_3_dialog_content = "(Hanya ada perselisihan bahwa saksi bukanlah seorang bangsawan, melainkan pelayan tua... Namun, itu bukan alasan yang valid untuk menyangkal keaslian dari surat wasiat.)",
  ui_story_5063_50631101_4_dialog_content = "(Tetapi jika surat wasiat diterima oleh pengadilan, Pam dan keluarganya akan kehilangan status mereka sebagai bangsawan. Bukankah itu juga akan mempengaruhi masa depannya?)",
  ui_story_5063_50631101_5_dialog_content = "(Aku tidak ingin mempertaruhkan persahabatan kita karena ini... Apa yang harus kulakukan?)",
  ui_story_5063_50631101_6_dialog_content = "Wanita Irridon? Aku tidak mengganggu, kan?",
  ui_story_5063_50631101_7_dialog_content = "Tolong jangan salah paham! A-Aku hanya ingin mengatakan... Tolong jangan biarkan pertemanan kita menghalangi memberikan penilaian yang adil!",
  ui_story_5063_50631101_8_dialog_content = "Demi White Night. Sebagai Ksatria Keadilan Lumopolis, kamu telah dipilih oleh Dewa Cahaya untuk melayani rakyat kota ini secara adil dan tanpa prasangka.",
  ui_story_5063_50631101_9_dialog_content = "Maafkan saya jika terdengar sombong, tetapi tolong... Jangan biarkan persahabatan kita merusak kesucian penilaian yang adil!",
  ui_story_5063_50631101_10_dialog_content = "Pam...",
  ui_story_5063_50631101_11_dialog_content = "Ayah saya mengajari saya sejak dulu bahwa pelayan keadilan yang sejati adalah yang tidak memihak.",
  ui_story_5063_50631101_12_dialog_content = "Tenang saja, saya akan mengumpulkan bukti yang diperlukan untuk memberikan penilaian yang adil dan jujur!",
  ui_story_5063_50631101_13_dialog_content = "Sudahkah kamu mencapai kesimpulan, ksatria wanita?",
  ui_story_5063_50631101_14_dialog_content = "Saya juga sangat menantikan putusan Anda, Nyonya!",
  ui_story_5063_50631101_15_dialog_content = "Ya, akhirnya aku mencapai sebuah keputusan.",
  ui_story_5063_50631101_16_dialog_content = "Demi White Night! Sesuai dengan hukum Lumopolis mengenai warisan dan wasiat terakhir, dengan ini aku menyatakan bahwa wasiat ini sah secara hukum.",
  ui_story_5063_50631101_17_dialog_content = "Tapi saksi itu hanyalah seorang pelayan biasa! Tentu Anda menyadari pelanggaran yang begitu mencolok, bukan?!",
  ui_story_5063_50631101_18_dialog_content = "Penilaian sembrono Anda akan mengguncang seluruh Lumopolis hingga ke dasar fondasinya!",
  ui_story_5063_50631101_19_dialog_content = "Tidak ada hukum di Lumopolis yang melarang seseorang untuk bertindak sebagai saksi hanya berdasarkan kedudukan ekonomi mereka. Ini hanyalah sebuah rumor yang ada di kalangan bangsawan.",
  ui_story_5063_50631101_20_dialog_content = "Selama seseorang jujur, rajin, dan tidak terlibat dalam kesalahan hukum, mereka berhak untuk menjadi saksi yang dapat dipercaya.",
  ui_story_5063_50631101_21_dialog_content = "Kamu... Dan kamu menyebut dirimu Ksatria Keadilan dari Lumopolis?!",
  ui_story_5063_50631101_22_dialog_content = "Ayah, berhenti! Ketika sekelompok siswa bangsawan menuduh saya mencuri Emblem Dawn dari Akademi, Lady Irridon lah yang mengungkap kebenaran di balik tindakan mereka!",
  ui_story_5063_50631101_23_dialog_content = "Prasangka kita terhadap Pak Jerry tidak berbeda dengan prasangka para bangsawan lain yang ditunjukkan kepada kita.",
  ui_story_5063_50631101_24_dialog_content = "Dalam hal apapun, saya percaya pada Lady Irridon dan kemampuannya untuk memberikan penilaian yang adil dan wajar.",
  ui_story_5063_50631101_25_dialog_content = "Bukan kamu juga, Pam...",
  ui_story_5063_50631101_26_dialog_content = "Jika ini benar-benar keinginan terakhir kakek, kita tidak punya pilihan selain menghormatinya.",
  ui_story_5063_50631101_27_dialog_content = "Huh, bagaimana bisa situasinya jadi seperti ini? Padahal aku pikir aku bisa memberimu sedikit lebih banyak...",
  ui_story_5063_50631101_28_dialog_content = "Mungkin pria tua itu memang tidak pernah menginginkan anak seperti aku, setelah semua.",
  ui_story_5063_50631101_29_dialog_content = "Itu sama sekali tidak benar, Ayah! Aku tahu selama ini selalu ada jarak yang sangat besar antara kamu...",
  ui_story_5063_50631101_30_dialog_content = "Tapi kakek tidak pernah mengeluh atau berbicara buruk tentang kamu setiap kali saya berkunjung! Kamu juga punya cara diam-diam untuk merawatnya, 'kan?",
  ui_story_5063_50631101_31_dialog_content = "Jika kalian berdua hanya mengambil langkah pertama mendekati satu sama lain, aku yakin kalian bisa menutup jarak di antara kalian!",
  ui_story_5063_50631101_32_dialog_content = "Ayah...",
  ui_story_5063_50631101_33_dialog_content = "(Apakah ayahku dan aku memiliki jarak yang sama dan tak terjangkau di antara kami?)",
  ui_story_5063_50631101_34_dialog_content = "(Meskipun keadaan seperti sekarang, keputusan saya masih sangat berbeda dari keputusan dia.)",
  ui_story_5063_50631101_35_dialog_content = "(Bisakah itu berarti... Penilaian saya masih dipengaruhi oleh emosiku?!)",
  ui_story_5063_50631101_36_dialog_content = "(Bukan persahabatan dengan Pam, melainkan keinginan untuk memberontak terhadap ayahku... Itulah yang mendorongku untuk mengeluarkan putusan ini!)",
  ui_story_5063_50631101_37_dialog_content = "Mengapa Anda jadi diam, Nona Irridon? Jika itu karena nasib kami... Maka dengan rendah hati saya meminta Anda untuk tidak merasa kasihan pada kami.",
  ui_story_5063_50631101_38_dialog_content = "Tidak ada apa-apa, saya hanya teringat akan ayah saya sendiri. Jika dia masih bersama kita hari ini... Apakah dia akan memberikan keputusan yang berbeda?",
  ui_story_5063_50631101_39_dialog_content = "Begitu, ya. Apakah ini berarti Anda ingin lebih seperti ayah Anda, Nona Irridon?",
  ui_story_5063_50631101_40_dialog_content = "Tidak akan pernah!",
  ui_story_5063_50631101_41_dialog_content = "Maafkan saya jika salah bicara, tapi apakah Anda benar-benar sangat menentang gagasan ini?",
  ui_story_5063_50631101_42_dialog_content = "Jika tidak, mengapa keputusan ayahmu sangat mengkhawatirkan kamu?",
  ui_story_5063_50631101_43_dialog_content = "Aku…",
  ui_story_5063_50631101_44_dialog_content = "Kamu memiliki poin. Mengapa aku begitu peduli tentang keputusan yang akan dicapai ayahku? Dan mengapa aku menjadi Justice Knight pada awalnya?",
  ui_story_5063_50631101_45_dialog_content = "<size=45>Inilah saatnya! Tangkap semua orang di rumah ini!</size>",
  ui_story_5063_50631101_46_dialog_content = "<size=45>Benar!</size>",
  ui_story_5063_50631101_47_dialog_content = "H-hah?!",
  ui_story_5063_50631101_48_dialog_content = "Pam! Lepaskan putriku, kalian bajingan!!",
  ui_story_5063_50631101_49_dialog_content = "Apakah ini benar-benar terjadi? Surat wasiat yang ditulis oleh masterku... Sudah diterima oleh pengadilan?",
  ui_story_5063_50631101_50_dialog_content = "Mengapa kalian menangkap keluarga ini? Perintah siapa yang kalian ikuti?",
  ui_story_5063_50631101_51_dialog_content = "Anggota keluarga Pyrrhus mengabaikan peringatan dan meneliti kristal merah. Lord Kota dan Hakim Agung telah mengeluarkan perintah penangkapan untuk semua anggota keluarga.",
  ui_story_5063_50631101_52_dialog_content = "Ini adalah putusan dan surat perintah penangkapan! Pihak yang tidak terlibat, segera pergi, atau kami akan menangkap kalian semua!",
  ui_story_5063_50631101_53_dialog_content = "T-Tunggu! Saya bukan bagian dari keluarga ini!",
  ui_story_5063_50631101_54_dialog_content = "Apakah Anda terlibat atau tidak, kami akan menyelidikinya secara menyeluruh. Sekarang, lanjutkan!",
  ui_story_5063_50631101_55_dialog_content = "Pam...",
  ui_story_5063_50631101_56_dialog_content = "Maafkan saya, Lady Irridon... Saya bermaksud mengundang Anda untuk makan malam bersama keluarga saya, tetapi sepertinya kami harus menjadwalkan ulang.",
  ui_story_5063_50631101_57_dialog_content = "Tetap kuat! Aku akan mencari cara untuk menyelamatkanmu!",
  ui_story_5063_50631101_58_dialog_content = "Kamu sudah melakukan banyak hal untukku, jadi tolong jangan repotkan dirimu lagi demi aku... Hal itu hanya akan membebani hatiku lebih banyak lagi.",
  ui_story_5063_50631101_59_dialog_content = "Bahkan aku tahu bahwa penelitian tentang kristal merah itu sangat dilarang. Meskipun orang tua dan aku tidak melakukan kejahatan apa pun...",
  ui_story_5063_50631101_60_dialog_content = "Ketika salah satu dari kita dinyatakan bersalah, seluruh keluarga kita menanggung beban dosa mereka.",
  ui_story_5063_50631101_61_dialog_content = "Tapi jangan khawatir. Aku akan mengambil ini sebagai kesempatan untuk menunjukkan pertobatan dan pengabdianku kepada Dewa Cahaya, dan terus berjuang untuk menjadi seorang biarawati di Kuil Lumopolis!",
  ui_story_5063_50631101_62_dialog_content = "Apabila hari itu tiba, saya yakin Anda juga akan menjadi hakim penuh di Balai Kehakiman.",
  ui_story_5063_50631101_63_dialog_content = "Saya... akan berusaha sebaik mungkin! Suatu hari nanti, saya akan menjadi hakim yang murni dan adil!",
  ui_story_5063_50631101_64_dialog_content = "Ayo! Tidak ada waktu untuk ngobrol-ngobrol!",
  ui_story_5063_50631101_65_dialog_content = "Sampai jumpa lagi, temanku!",
  ui_story_5063_50631101_66_dialog_content = "Dadah...",
  ui_story_5063_50631103_1_dialog_content = "Apakah ini salah satu putusan ayahku lagi?",
  ui_story_5063_50631103_2_dialog_content = "Tidak... Ini adalah laporan investigasi pribadi yang ditulis oleh ayahku sendiri.",
  ui_story_5063_50631103_3_dialog_content = "\"Sebelum meninggal, baron yang telah almarhum mengetahui bahwa seluruh keluarganya akan segera ditangkap.\"",
  ui_story_5063_50631103_4_dialog_content = "\"Ketakutan bahwa putranya dan cucunya akan terlibat, dia merancang satu rencana terakhir yang penuh keputusasaan.\"",
  ui_story_5063_50631103_5_dialog_content = "\"Dengan mewariskan gelar dan hartanya kepada pelayan terdekatnya melalui wasiat, baron yang telah meninggal percaya bahwa keluarganya akan terhindar.\"",
  ui_story_5063_50631103_6_dialog_content = "Apa...? Bagaimana dan kapan ayahku menemukan rincian mengejutkan seperti itu?",
  ui_story_5063_50631103_7_dialog_content = "Meskipun untuk melindungi keluarganya, kakek Pam tidak memiliki hak untuk menyeret pelayan yang tidak bersalah!",
  ui_story_5063_50631103_8_dialog_content = "<size=45>!!!</size>",
  ui_story_5063_50631103_9_dialog_content = "Jadi ayahku tahu tentang niat baron sejak awal. Apakah itu sebabnya dia memilih untuk membatalkan wasiatnya?",
  ui_story_5063_50631103_10_dialog_content = "Seperti yang diharapkan... Keputusan Ayah memang benar, setelah semua...",
  ui_story_5063_50631103_11_dialog_content = "A-apa yang telah kulakukan...?",
  ui_story_5063_50631201_1_dialog_content = "Saya telah mencari seluruh Halaman Lumopolis, tetapi masih belum ada tanda-tanda wanita berpakaian hitam itu. Bisakah dia melarikan diri ke Lower Lumopolis?",
  ui_story_5063_50631201_2_dialog_content = "Aku jarang pergi ke Lower Lumopolis sebelumnya... Bahkan suasana di sini sangat berbeda dari bagian atas kota.",
  ui_story_5063_50631201_3_dialog_content = "Aku merasa banyak mata memperhatikanku saat berjalan di jalanan... Apakah kehadiran seorang Justice Knight benar-benar begitu mencolok di sini?",
  ui_story_5063_50631201_4_dialog_content = "Apa yang kamu lakukan di sini, Justice Knight?",
  ui_story_5063_50631201_5_dialog_content = "K-Ketua Hakim?!",
  ui_story_5063_50631201_6_dialog_content = "A-Aku minta maaf, tetapi karena ketidakcakapanku, aku belum berhasil menangkap wanita berbaju hitam itu.",
  ui_story_5063_50631201_7_dialog_content = "Tetapi selama pengejaran saya, saya berhasil menyelesaikan sejumlah kasus yang tidak terkait untuk beberapa penduduk setempat...",
  ui_story_5063_50631201_8_dialog_content = "Wanita berbaju hitam? Wanita berbaju hitam yang mana?",
  ui_story_5063_50631201_9_dialog_content = "Hah? Orang yang menerobos masuk ke Hall of Justice dan meminta Anda membersihkan namanya...",
  ui_story_5063_50631201_10_dialog_content = "Hmm... sekarang setelah kamu menyebutkannya, aku samar-samar mengingat orang seperti itu.",
  ui_story_5063_50631201_11_dialog_content = "Tapi kita bisa menunda itu untuk sekarang. Saya punya tugas yang lebih penting untuk kamu.",
  ui_story_5063_50631201_12_dialog_content = "Kami mendapat informasi yang menyatakan bahwa Mirren Gautier mungkin terlibat dalam pengkhianatan. Selidiki apakah informasi ini benar adanya.",
  ui_story_5063_50631201_13_dialog_content = "A-Apakah kamu yakin ingin menyerahkan tugas penting ini padaku?",
  ui_story_5063_50631201_14_dialog_content = "Eh, maksud saya... Terima kasih telah mempercayai saya, Hakim Ketua! Saya akan segera memulai penyelidikan tentang dugaan pengkhianatan Mirren Gautier...",
  ui_story_5063_50631201_15_dialog_content = "Tunggu... Ada yang berencana memberontak melawan kota?!",
  ui_story_5063_50631201_16_dialog_content = "Tugas ini menyangkut kelangsungan hidup Lumopolis, yang berarti harus dilaksanakan dengan sempurna, tanpa ruang untuk kesalahan. Apakah kamu mengerti?",
  ui_story_5063_50631201_17_dialog_content = "Ya, Hakim Ketua!",
  ui_story_5063_50631201_18_dialog_content = "Aku tidak akan mengizinkan siapa pun untuk mencemari kota yang telah aku bersumpah untuk melindungi!",
  ui_story_5063_50631201_19_dialog_content = "Saya juga tidak akan mengizinkan diri saya untuk mengecewakan Anda, Ketua Hakim...",
  ui_story_5063_50631201_20_dialog_content = "Perlindungan! Kesetiaan! Kemuliaan!",
  ui_story_5063_50631201_21_dialog_content = "Lagi... Dari mana mereka terus berdatangan?!",
  ui_story_5063_50631201_22_dialog_content = "Mohon mundur ke tempat yang aman, Hakim Ketua! Saya bisa menghadapi mereka!",
  ui_story_5063_50631201_23_dialog_content = "Menyerang!",
  ui_story_5063_50631302_1_dialog_content = "(Hakim Ketua mengatakan bahwa dia tidak bisa melihat penjaga-penjaga aneh itu...)",
  ui_story_5063_50631302_2_dialog_content = "(Bisakah hanya aku yang bisa melihat mereka?)",
  ui_story_5063_50631302_3_dialog_content = "Apakah mataku menipuku... Apakah itu kamu, Wanita Irridon?",
  ui_story_5063_50631302_4_dialog_content = "Pam?!",
  ui_story_5063_50631302_5_dialog_content = "Demi White Night! Ini memang kamu! Tapi apa yang kamu lakukan di Lumopolis Bawah?",
  ui_story_5063_50631302_6_dialog_content = "Kupikir aku tidak akan melihatmu lagi dalam waktu yang lebih lama...",
  ui_story_5063_50631302_7_dialog_content = "Aku punya pekerjaan yang harus dikerjakan di sini. Apakah kamu... baik-baik saja?",
  ui_story_5063_50631302_8_dialog_content = "Ya! Seperti yang bisa kamu lihat, tubuh dan semangatku dalam kondisi sempurna!",
  ui_story_5063_50631302_9_dialog_content = "Katanya, seluruh keluarga kamu kehilangan Luminatics mereka...",
  ui_story_5063_50631302_10_dialog_content = "Ini... memang sudah seharusnya. Bagaimanapun juga, keluarga kita bertanggung jawab atas dosa yang tak bisa diampuni itu.",
  ui_story_5063_50631302_11_dialog_content = "Berdasarkan hukum Lumopolis, hukuman kami sepenuhnya pantas.",
  ui_story_5063_50631302_12_dialog_content = "...D-Dalam hal apapun, aku melihat ini semua sebagai pengalaman baru! Bagaimanapun, aku belum pernah ke Lower Lumopolis sebelum pengasingan kita!",
  ui_story_5063_50631302_13_dialog_content = "Selama keluarga kita tetap bersama, kita bisa bertahan hidup di mana saja!",
  ui_story_5063_50631302_14_dialog_content = "Tapi bagaimana dengan masa percobaan Kuil Lumopolis...?",
  ui_story_5063_50631302_15_dialog_content = "Yah, memang benar bahwa aku tidak punya cara untuk kembali sekarang...",
  ui_story_5063_50631302_16_dialog_content = "Namun demikian, keyakinanku tetap teguh. Setiap hari aku berdoa kepada God of Light untuk pengampunan, seperti yang selalu kulakukan di masa lalu.",
  ui_story_5063_50631302_17_dialog_content = "Selama aku bertahan, aku yakin akan ada tempat untukku di Kuil Lumopolis di masa depan!",
  ui_story_5063_50631302_18_dialog_content = "Optimisme murni Anda membuat saya tak bisa berkata-kata...",
  ui_story_5063_50631302_19_dialog_content = "Tidak seperti kamu, aku penuh keraguan dan kekhawatiran, sehingga aku bahkan tidak bisa menyelesaikan tugas yang ada di depanku.",
  ui_story_5063_50631302_20_dialog_content = "Tidak perlu membandingkan diri dengan orang lain, tahu? Setiap orang itu unik, dan punya masalah mereka sendiri untuk dipecahkan dalam hidup.",
  ui_story_5063_50631302_21_dialog_content = "Menurut pandangan saya, Nona Irridon, Anda sudah merupakan orang yang luar biasa dan pekerja keras. Apakah Anda yakin tidak terlalu banyak menuntut diri sendiri?",
  ui_story_5063_50631302_22_dialog_content = "Kamu... Benar-benar berpikir begitu?",
  ui_story_5063_50631302_23_dialog_content = "Ya ampun... Kenapa tiba-tiba aku yang sedang diberi dukungan?",
  ui_story_5063_50631302_24_dialog_content = "...Tapi cukup tentang itu. Jika kamu atau keluargamu mengalami masalah, kamu harus memberitahuku segera!",
  ui_story_5063_50631302_25_dialog_content = "Ha ha ha! Terima kasih atas perhatiannya, Lady Irridon!",
  ui_story_5063_50631302_26_dialog_content = "Oh? Sudah waktunya makan siang? Jika kamu belum makan, maukah bergabung dengan kami?",
  ui_story_5063_50631302_27_dialog_content = "Jika tidak terlalu merepotkan, maka ya...",
  ui_story_5063_50631302_28_dialog_content = "Setelah semua, ini adalah... Pertama kalinya seorang teman mengundang saya untuk makan bersama. Itu akan menjadi kehormatanku untuk bergabung dengan Anda!",
  ui_story_5063_50631302_29_dialog_content = "Makanan akan siap dalam beberapa menit saja!",
  ui_story_5063_50631302_30_dialog_content = "Sejak pertama kali kita bertemu, saya ingin mengundang Anda untuk makan malam bersama keluarga saya...",
  ui_story_5063_50631302_31_dialog_content = "Saya mulai berpikir bahwa ini mungkin bukan takdir... Tapi kemudian takdir menyatukan kita lagi, di sini di Lower Lumopolis!",
  ui_story_5063_50631302_32_dialog_content = "Aku tahu ini bukan makan malam, dan tidak banyak pilihan hidangan...",
  ui_story_5063_50631302_33_dialog_content = "Tetapi melalui belajar dan berlatih, aku telah belajar cara membuat hidangan yang layak dari bahan-bahan langka yang tersedia untuk kita di sini!",
  ui_story_5063_50631302_34_dialog_content = "Ya, dan kamu harus berterima kasih padaku karena kemampuan memasak yang kamu warisi, Pam! Ha ha ha ha!",
  ui_story_5063_50631302_35_dialog_content = "Saya hanya bersyukur bahwa saya tidak mewarisi sifat menyombongkan Anda juga, Ayah!",
  ui_story_5063_50631302_36_dialog_content = "P-Pam! Bagaimana kamu bisa mengejek ayahmu yang malang di depan Lady Irridon?!",
  ui_story_5063_50631302_37_dialog_content = "Heehee, aku hanya menggoda! Lagipula, ibu sering melakukannya padamu, bukan?",
  ui_story_5063_50631302_38_dialog_content = "Anda harus memaafkan putri saya atas kelakuan bodohnya, Nona Irridon. Silakan, menikmati.",
  ui_story_5063_50631302_39_dialog_content = "Saya bisa menjamin, kamu tidak akan menemukan rasa seperti ini di Lumopolis Gardens! Hahahaha!",
  ui_story_5063_50631302_40_dialog_content = "Aku tahu ini tidak terlihat sangat mewah, tapi...",
  ui_story_5063_50631302_41_dialog_content = "Nyam...",
  ui_story_5063_50631302_42_dialog_content = "Bagaimana? Cocok dengan selera Anda?",
  ui_story_5063_50631302_43_dialog_content = "<size=45>!!!</size>",
  ui_story_5063_50631302_44_dialog_content = "...Enak sekali.",
  ui_story_5063_50631302_45_dialog_content = "Faktanya, setelah mencicipinya, tubuhku jadi bergolak dengan energi baru!",
  ui_story_5063_50631302_46_dialog_content = "Saya tidak pernah tahu bahwa semangkuk sup bisa membuat saya merasa sangat luar biasa...",
  ui_story_5063_50631302_47_dialog_content = "Kamu tidak kebetulan menambahkan ramuan Lumina ke dalamnya, bukan Pam?",
  ui_story_5063_50631302_48_dialog_content = "Dan di mana di muka bumi ini saya bisa menemukan uang untuk bahan yang begitu mahal, Lady Irridon?",
  ui_story_5063_50631302_49_dialog_content = "Tidak, jika ada... Yang kamu rasakan hanya bisa dijelaskan sebagai <color=#FFB400>cinta kasih keluarga</color>.",
  ui_story_5063_50631302_50_dialog_content = "\"Cinta sebuah keluarga...\"",
  ui_story_5063_50631302_51_dialog_content = "Sekali lagi, Anda harus memaafkan putri saya, Lady Irridon. Ucapannya bisa sedikit membingungkan kadang-kadang.",
  ui_story_5063_50631302_52_dialog_content = "Sebaliknya, saya sangat berterima kasih kepada Pam karena telah membagikan pemikirannya dengan saya.",
  ui_story_5063_50631302_53_dialog_content = "Tidak hanya itu, saya juga merasa perlu meminta maaf kepada Anda mengenai keinginan ayah Anda...",
  ui_story_5063_50631302_54_dialog_content = "Tidak perlu, Lady. Itu semua di masa lalu, dan aku sudah menerima kenyataannya sejak lama.",
  ui_story_5063_50631302_55_dialog_content = "Ketika kami tiba di Lower Lumopolis, kami tidak berbeda dengan rakyat jelata yang dulu kami pandang dengan penghinaan. Awalnya, saya pikir hidup kami akan dipenuhi dengan penderitaan dan kesengsaraan.",
  ui_story_5063_50631302_56_dialog_content = "Namun, sebagai rakyat jelata, saya segera menemukan bahwa orang-orang di sekitar kami jauh lebih baik dalam membantu dan merawat satu sama lain daripada bangsawan mana pun yang pernah saya kenal.",
  ui_story_5063_50631302_57_dialog_content = "Di Lumopolis, para bangsawan sering harus menginjak-injak orang di bawah mereka untuk mempertahankan posisi mereka.",
  ui_story_5063_50631302_58_dialog_content = "Satu-satunya cara untuk menghindarinya adalah dengan mendorong orang lain jatuh dan menginjak-injak mereka.",
  ui_story_5063_50631302_59_dialog_content = "Pada akhirnya, apa gunanya kembali ke kehidupan yang penuh eksploitasi seperti itu?",
  ui_story_5063_50631302_60_dialog_content = "Penyesalan saya hanya karena Pam kehilangan kesempatan untuk bergabung dengan Lumopolis Temple...",
  ui_story_5063_50631302_61_dialog_content = "Namun sebagai cabang dari keluarga Pyrrhus, kamu tidak pernah secara langsung bertanggung jawab atas kejahatan mereka.",
  ui_story_5063_50631302_62_dialog_content = "Tidak hanya itu, saya juga tidak bisa membayangkan siapa yang lebih pantas menjadi biarawati daripada Pam. Ketaatannya dan kepribadiannya menunjukkan hal tersebut.",
  ui_story_5063_50631302_63_dialog_content = "Setelah menyelesaikan tugas yang sedang saya kerjakan, saya akan melaporkan ini kepada Ketua Hakim. Mungkin dia akan mengizinkan dia kembali ke Kuil Lumopolis!",
  ui_story_5063_50631303_1_dialog_content = "\"Keluarga Pyrrhus, bersama keluarga Gautier, menggunakan Eclipsite yang ditingkatkan untuk mengatur aksi pemberontakan keras...\"",
  ui_story_5063_50631303_2_dialog_content = "\"Setiap anggota dari keluarga mereka masing-masing telah dijatuhi hukuman mati. Jika ada perlawanan lebih lanjut, mereka akan dieksekusi di tempat.\"",
  ui_story_5063_50631303_3_dialog_content = "I-Ini juga salah satu putusan ayahku...?",
  ui_story_5063_50631303_4_dialog_content = "Tapi ini benar-benar bertentangan dengan hasil investigasi saya!",
  ui_story_5063_50631303_5_dialog_content = "Memang benar bahwa kedua keluarga diasingkan ke Lumopolis Bawah sebagai akibat dari penelitian keluarga Pyrrhus tentang kristal merah...",
  ui_story_5063_50631303_6_dialog_content = "Tapi saat ini, yang bersekongkol dengan Eclipsite untuk menganiaya keluarga Pyrrhus adalah tidak lain dari Mirren Gautier dan kerabatnya!",
  ui_story_5063_50631303_7_dialog_content = "Tentu saja, ayahku tidak mungkin melewatkan detail penting seperti itu...",
  ui_story_5063_50631303_8_dialog_content = "Jadi, mengapa dia menghakimi seperti ini?",
  ui_story_5063_50631303_9_dialog_content = "Kasus ini berdampak pada seluruh Lumopolis dan keamanannya... Apakah saya benar-benar cukup percaya diri dengan penilaian saya sendiri untuk menolak putusan ayah saya?",
  ui_story_5063_50631303_10_dialog_content = "Mungkinkah... Apakah dia menemukan sesuatu yang lain?",
  ui_story_5063_50631303_11_dialog_content = "Dalam hal ini, tidak ada alasan untuk terus menganiaya keluarga yang tidak bersalah karena hal ini!",
  ui_story_5063_50631303_12_dialog_content = "Ayah...",
  ui_story_5063_50631303_13_dialog_content = "Sepertinya jarak di antara kita... semakin bertambah besar...",
  ui_story_5063_50631601_1_dialog_content = "...Itu menyimpulkan laporan penyelidikan saya.",
  ui_story_5063_50631601_2_dialog_content = "Baik, aku akan melaporkan hasil penyelidikan ini ke Hakim Ketua segera!",
  ui_story_5063_50631601_3_dialog_content = "Terima kasih saya!",
  ui_story_5063_50631601_4_dialog_content = "Nah, sekarang masih ada satu hal terakhir yang harus kulakukan...",
  ui_story_5063_50631601_5_dialog_content = "Apakah Anda telah membuat kemajuan dalam misi Anda, Wanita Irridon?",
  ui_story_5063_50631601_6_dialog_content = "Er... Ya. Bahkan, masalah ini hampir selesai sekarang.",
  ui_story_5063_50631601_7_dialog_content = "Lalu... Apakah kamu akan segera pergi?",
  ui_story_5063_50631601_8_dialog_content = "Jangan salah paham! Saya hanya berpikir bahwa jika kalian tidak terburu-buru, kalian bisa datang ke rumah kami dan makan malam bersama kami.",
  ui_story_5063_50631601_9_dialog_content = "Ibu dan Ayah sedang menyiapkan pesta saat ini!",
  ui_story_5063_50631601_10_dialog_content = "Ahhhh!",
  ui_story_5063_50631601_11_dialog_content = "<size=45>Bersihkan pengkhianat! Bersihkan pengkhianat! Bersihkan pengkhianat!</size>",
  ui_story_5063_50631601_12_dialog_content = "Mengapa para penjaga itu menangkap semua orang?!",
  ui_story_5063_50631601_13_dialog_content = "<size=45>Bersihkan pengkhianat! Bersihkan pengkhianat! Bersihkan pengkhianat!</size>",
  ui_story_5063_50631601_14_dialog_content = "(Tampaknya Hakim Ketua sudah memberikan perintah untuk menangkap keluarga Gautier... Tapi apa hubungannya dengan keluarga Pyrrhus?)",
  ui_story_5063_50631601_15_dialog_content = "(Bisakah itu berarti Hakim Ketua mengira kedua keluarga tersebut bersekongkol satu sama lain?)",
  ui_story_5063_50631601_16_dialog_content = "(Tapi itu berarti Pam adalah...)",
  ui_story_5063_50631601_17_dialog_content = "Hah? Ayah!",
  ui_story_5063_50631601_18_dialog_content = "Pam...! Lupakan aku!",
  ui_story_5063_50631601_19_dialog_content = "<size=45>Lari, Pam! Lari secepat mungkin!!!</size>",
  ui_story_5063_50631601_20_dialog_content = "Mengapa mereka menangkap ayah saya, Lady Irridon?!",
  ui_story_5063_50631601_21_dialog_content = "Kami tidak pernah melanggar hukum sejak kami datang ke Lower Lumopolis, jadi mengapa... Beritahu saya, Lady Irridon!",
  ui_story_5063_50631601_22_dialog_content = "Mungkinkah ini ada hubungannya dengan misimu...?",
  ui_story_5063_50631601_23_dialog_content = "Aku tidak bisa memberitahumu tentang tugasku, Pam. Setidaknya tidak sekarang... Tapi aku bisa menjamin, ini tidak ada hubungannya dengan ini!",
  ui_story_5063_50631601_24_dialog_content = "Untuk saat ini, dengarkan saja ayahmu dan lari!",
  ui_story_5063_50631601_25_dialog_content = "<size=45>Ayo pergi!</size>",
  ui_story_5063_50631601_26_dialog_content = "Apakah ada anggota keluarga Pyrrhus yang berhasil kabur ke sana?",
  ui_story_5063_50631601_27_dialog_content = "Singkirkan kecurigaan kalian, pengawal; gadis itu bukan anggota keluarga Pyrrhus. Dia hanya panik melihat keadaan dan lari.",
  ui_story_5063_50631601_28_dialog_content = "Mengerti. Mari kita cari di sekitar sana lagi!",
  ui_story_5063_50631601_29_dialog_content = "Pam...",
  ui_story_5063_50631601_30_dialog_content = "Heheh, jadi bahkan Justice Knight juga mampu berbohong, ya?",
  ui_story_5063_50631601_31_dialog_content = "Ini kamu! Aku sudah mencari kamu untuk beberapa waktu sekarang... Betapa baiknya kamu menyerahkan diri kepadaku!",
  ui_story_5063_50631601_32_dialog_content = "Kamu, seorang Ksatria Keadilan dari Lumopolis, membiarkan penjahat besar seperti itu lolos dari cengkramanmu...",
  ui_story_5063_50631601_33_dialog_content = "Kejahatan apa yang menurutmu telah kamu lakukan?",
  ui_story_5063_50631601_34_dialog_content = "Sebagai Justice Knight, menjaga hukum Lumopolis bukan satu-satunya tanggung jawab saya. Saya juga memiliki kewajiban untuk melindungi orang-orang yang tidak bersalah di kota ini!",
  ui_story_5063_50631601_35_dialog_content = "Pasti ada semacam kesalahpahaman! Kenapa lagi Hakim Agung menangkap seluruh keluarga Pyrrhus...?",
  ui_story_5063_50631601_36_dialog_content = "Aku akan menjelaskan semuanya kepadanya saat aku mendapat kesempatan, dan membersihkan nama Pam dan keluarganya dari segala kesalahan!",
  ui_story_5063_50631601_37_dialog_content = "Oh? Kalau begitu, kenapa kau mengejarku dengan begitu gigih?",
  ui_story_5063_50631601_38_dialog_content = "Karena Anda...",
  ui_story_5063_50631601_39_dialog_content = "Hm?",
  ui_story_5063_50631601_40_dialog_content = "Kau...",
  ui_story_5063_50631601_41_dialog_content = "<size=45><color=#FFB400>Pam</color>?!</size>",
  ui_story_5063_50631601_42_dialog_content = "Sudah lama sekali sejak ada orang yang memanggilku dengan nama itu...",
  ui_story_5063_50631601_43_dialog_content = "Tapi mungkin kamu lebih mengenal saya dengan salah satu nama di daftar buronanmu: <color=#FFB400>PalomaPyrrhus</color>.",
  ui_story_5063_50631601_44_dialog_content = "Selama ini kamu berbohong padaku...?",
  ui_story_5063_50631601_45_dialog_content = "Oh? Heheh, sepertinya kamu memang melupakan setelah semuanya...",
  ui_story_5063_50631601_46_dialog_content = "Maukah kamu ceritakan padaku apa yang terjadi padamu?",
  ui_story_5063_50631601_47_dialog_content = "Kamu yang memintaku untuk menjelaskan situasiku padamu.",
  ui_story_5063_50631601_48_dialog_content = "Namun tepat ketika aku akan melakukannya, \"Pam\" tiba-tiba terlepas dari tubuhku.",
  ui_story_5063_50631601_49_dialog_content = "Orang yang kamu kenal sebagai Pam itu aku, tapi sekaligus bukan aku...",
  ui_story_5063_50631601_50_dialog_content = "Pada saat ini juga, dia seharusnya bersembunyi di suatu tempat dan merasakan rasa sakit yang sama yang pernah kurasakan lebih dari satu dekade yang lalu... Kasihan anak kecil itu.",
  ui_story_5063_50631601_51_dialog_content = "Jadi ketika kamu memaksa masuk ke Hall of Justice... Itu untuk melaporkan tindakan pemberontakan ini?",
  ui_story_5063_50631601_52_dialog_content = "Seharusnya aku menyadarinya lebih cepat...",
  ui_story_5063_50631601_53_dialog_content = "Tapi masih ada waktu! Saya akan melaporkan temuan saya kepada Hakim Ketua, dan membuktikan Pam... dan Anda, tidak bersalah!",
  ui_story_5063_50631601_54_dialog_content = "Kita hanya perlu menunggu dan melihat saja, bukan?",
  ui_story_5063_50631601_55_dialog_content = "Justice Knight!",
  ui_story_5063_50631601_56_dialog_content = "Pelarian itu tepat di depan mata Anda. Kenapa belum menangkapnya saja?",
  ui_story_5063_50631601_57_dialog_content = "Sebelum itu, saya ingin tahu apa yang mendorong Anda untuk mengesahkan penangkapan keluarga Gautier dan Pyrrhus.",
  ui_story_5063_50631601_58_dialog_content = "Bukankah ini semua berkat penyelidikan Anda?",
  ui_story_5063_50631601_59_dialog_content = "Tapi penyelidikan saya sudah membuktikan bahwa sebagian besar anggota keluarga Pyrrhus adalah korban dalam kasus ini, bukan pelakunya!",
  ui_story_5063_50631601_60_dialog_content = "Kedua keluarga Gautier dan Pyrrhus terlibat dalam eksperimen terlarang. Bukankah itu benar?",
  ui_story_5063_50631601_61_dialog_content = "Ya, tetapi mereka sudah dihukum atas kejahatan itu. Selain itu, Anda tidak bisa menyalahkan setiap orang dalam keluarga mereka untuk itu.",
  ui_story_5063_50631601_62_dialog_content = "Justice Knight! Apakah aku harus memeriksa satu per satu untuk melihat siapa yang berubah menjadi monster dengan sengaja karena pengkhianatan dan siapa yang tidak?",
  ui_story_5063_50631601_63_dialog_content = "Untuk menjaga keamanan dan stabilitas Lumopolis, kita tidak bisa mengabaikan risiko potensial apa pun.",
  ui_story_5063_50631601_64_dialog_content = "Lalu bagaimana dengan orang-orang yang tidak bersalah yang sama sekali tidak terlibat dalam eksperimen tersebut?",
  ui_story_5063_50631601_65_dialog_content = "Mereka tidak menjadi monster... Mereka tidak melakukan apa-apa sama sekali! Jadi, mengapa mereka harus menanggung kesalahan dan kehilangan nyawa mereka karena itu?",
  ui_story_5063_50631601_66_dialog_content = "Tak bersalah? Sungguh lelucon! Keluarga Pyrrhus memang bersalah sejak awal. Ketika Hall of Justice menjatuhkan hukuman pengasingan ke Lower Lumopolis, itu sudah merupakan belas kasihan.",
  ui_story_5063_50631601_67_dialog_content = "Kini, mereka bahkan terlibat dalam kasus pengkhianatan ini... Mengapa kita harus memberi kelonggaran pada sekelompok calon penjahat dari Lower Lumopolis?",
  ui_story_5063_50631601_68_dialog_content = "Bagaimana Anda bisa menentukan apakah seseorang pantas mendapatkan perlakuan adil di bawah hukum hanya berdasarkan status dan tempat tinggal mereka?!",
  ui_story_5063_50631601_69_dialog_content = "Saya masih percaya penilaian Anda salah, Ketua Hakim——",
  ui_story_5063_50631601_70_dialog_content = "Ini juga keputusan yang akan dibuat ayahmu!",
  ui_story_5063_50631601_71_dialog_content = "Ayahmu adalah Hakim Ketua Lumopolis yang sangat dihormati. Apa, kamu sekarang melawan ayahmu sendiri?",
  ui_story_5063_50631601_72_dialog_content = "Aku…",
  ui_story_5063_50631601_73_dialog_content = "Heheh.",
  ui_story_5063_50631601_74_dialog_content = "Jadi Anda masih memiliki harapan untuk Lumopolis dan Hall of Justice, ya?",
  ui_story_5063_50631601_75_dialog_content = "Jangan biarkan mereka terus mencuci otakmu!",
  ui_story_5063_50631601_76_dialog_content = "Apa yang kamu lakukan?!",
  ui_story_5063_50631601_77_dialog_content = "Aku tidak akan mencoba menyakitimu, tapi sebaiknya kamu menjauh saja!",
  ui_story_5063_50631601_78_dialog_content = "Saatnya bagiku untuk membasmi sumber kejahatan yang bersembunyi di belakangmu!",
  ui_story_5063_50631601_79_dialog_content = "Justice Knight! Kalahkan wanita gila ini sekarang!",
  ui_story_5063_50631601_80_dialog_content = "...",
  ui_story_5063_50631601_81_dialog_content = "Berhenti, Paloma!",
  ui_story_5063_50631601_82_dialog_content = "Heheh... Kamu memang tak berbeda dari mereka.",
  ui_story_5063_50631601_83_dialog_content = "Tidak, Paloma... Aku hanya menolak untuk melihat kamu membuat kesalahan yang lebih besar lagi!",
  ui_story_5063_50631601_84_dialog_content = "Kamu bukanlah orang yang berhak menentukan apa yang benar atau salah. Tidak ada keadilan di Lumopolis!",
  ui_story_5063_50631601_85_dialog_content = "Membunuh seseorang juga tidak akan membawamu pada keadilan yang kau cari!",
  ui_story_5063_50631601_86_dialog_content = "Jika kamu tidak menangani masalah dari sumbernya, masalah itu tidak akan pernah hilang! Kamu bisa menghancurkan seluruh Lumopolis, dan itu pun tidak akan menghentikan siklus kebencian dan balas dendam!",
  ui_story_5063_50631601_87_dialog_content = "Seiring waktu, seseorang akan menciptakan Balai Kehakiman yang lebih arogan dan penuh prasangka!",
  ui_story_5063_50631601_88_dialog_content = "Lagipula, apakah kamu benar-benar akan melakukan ini? Bukankah kamu membenci para bangsawan karena menghabisi semua orang yang menghalangi mereka?",
  ui_story_5063_50631601_89_dialog_content = "Kamu mencoba menjadi seperti mereka?!",
  ui_story_5063_50631601_90_dialog_content = "Aku tidak seperti mereka!",
  ui_story_5063_50631601_91_dialog_content = "Lalu katakan padaku, apa bedanya antara tindakanmu saat ini dan tindakan mereka sendiri?",
  ui_story_5063_50631601_92_dialog_content = "...",
  ui_story_5063_50631601_93_dialog_content = "Dalam hal ini... Apakah kamu punya ide yang lebih baik?",
  ui_story_5063_50631601_94_dialog_content = "Waktu yang tepat!",
  ui_story_5063_50631601_95_dialog_content = "Cabik!",
  ui_story_5063_50631601_96_dialog_content = "Argh! Sial... Seharusnya aku sudah menduga akan ada serangan tiba-tiba...",
  ui_story_5063_50631601_97_dialog_content = "Sayang sekali untukmu... Kau meremehkanku...",
  ui_story_5063_50631601_98_dialog_content = "*batuk* Ksatria Keadilan... tangkap... wanita gila ini... *batuk*",
  ui_story_5063_50631601_99_dialog_content = "Aku akan berada di Hall of Justice... menunggu kabar darimu...",
  ui_story_5063_50631601_100_dialog_content = "Hahaha! Tepat sekali, lari dengan ekor... Di antara kakimu...",
  ui_story_5063_50631601_101_dialog_content = "Paloma! K-Kau baik-baik saja?",
  ui_story_5063_50631601_102_dialog_content = "Heheh, jadi akhirnya kau berhasil menangkapku. Sekarang kau bisa memberikan sesuatu yang akan membuat Hakim Ketua kesayanganmu bahagia.",
  ui_story_5063_50631601_103_dialog_content = "Kamu kehilangan terlalu banyak darah! Biar aku bantu!",
  ui_story_5063_50631601_104_dialog_content = "Hmph, kamu benar-benar tidak perlu terus berpura-pura, tahu. Kita sudah jauh melampaui itu sekarang.",
  ui_story_5063_50631601_105_dialog_content = "Hei! Apakah kamu tidak mendengar aku? Berhenti buang-buang waktu mencoba mengobati lukaku!",
  ui_story_5063_50631601_106_dialog_content = "Tapi aku ingin membantu! Apa lagi yang perlu aku lakukan?",
  ui_story_5063_50631601_107_dialog_content = "Tch, saya tidak butuh bantuan siapa pun, jadi berhenti saja. Yang saya butuhkan hanyalah keputusan yang adil... Pikir Anda bisa memberikan itu?",
  ui_story_5063_50631601_108_dialog_content = "Aku... Tentu saja bisa!",
  ui_story_5063_50631601_109_dialog_content = "Malam Putih di atas! Setelah penyelidikan yang luas, Hall of Justice menyimpulkan bahwa Mayor Pyrrhus dan keluarganya tidak memiliki niat pemberontakan. Selain itu, mereka tidak terlibat dalam eksperimen Eclipsite yang dilakukan oleh keluarga Gautier...",
  ui_story_5063_50631601_110_dialog_content = "Oleh karena itu, dengan ini saya menyatakan bahwa mereka semua... Tidak bersalah!",
  ui_story_5063_50631601_111_dialog_content = "...Tidak bersalah, ya?",
  ui_story_5063_50631601_112_dialog_content = "Heh, aku pasti sedang bermimpi.",
  ui_story_5063_50631601_113_dialog_content = "Paloma? Ke-Kemana kamu pergi?",
  ui_story_5063_50631601_114_dialog_content = "Jika ini memang mimpi, mungkin saatnya aku benar-benar bangun.",
  ui_story_5063_50631601_115_dialog_content = "Nah, sekarang kau...",
  ui_story_5063_50631601_116_dialog_content = "Aku ingin tahu apakah kamu akan melakukan hal yang sama?",
  ui_story_5063_50631601_117_dialog_content = "Sungguh... Kenapa kamu ingin menjadi Justice Knight?",
  ui_story_5063_50631701_1_dialog_content = "Tempat apa ini? Dan... Ke mana aku pergi?",
  ui_story_5063_50631701_2_dialog_content = "Hall of Justice?",
  ui_story_5063_50631701_3_dialog_content = "Sungguh... Kenapa kamu ingin menjadi Justice Knight?",
  ui_story_5063_50631701_4_dialog_content = "Aku bahkan tidak ingat alasan awalnya mengapa aku ingin bekerja di Hall of Justice...",
  ui_story_5063_50631701_5_dialog_content = "Saya gagal dalam setiap tugas yang diberikan oleh Ketua Hakim.",
  ui_story_5063_50631701_6_dialog_content = "Dan setiap keputusan yang telah saya buat adalah kebalikan dari apa yang telah ayah putuskan.",
  ui_story_5063_50631701_7_dialog_content = "Saya mengatakan ingin mengubah Lumopolis menjadi lebih baik, tapi... Apa yang benar-benar bisa saya capai dengan sendirian?",
  ui_story_5063_50631701_8_dialog_content = "<color=#e8d9bb>Ngungg...</color>",
  ui_story_5063_50631701_9_dialog_content = "Hah? Apa itu tadi?",
  ui_story_5063_50631701_10_dialog_content = "<color=#e8d9bb>Ngungg...</color>",
  ui_story_5063_50631701_11_dialog_content = "Mengapa kaca pembesar saya terbang keluar dari saku saya? Tunggu, ada sesuatu yang aneh di lensanya...",
  ui_story_5063_50631701_12_dialog_content = "Apa? A-Ada sosok di lensa!",
  ui_story_5063_50631701_13_dialog_content = "Tunggu, sosok itu... Apakah itu Chief Judge?",
  ui_story_5063_50631701_14_dialog_content = "Tapi ada sesuatu yang berbeda pada wajah Chief Judge. Terlihat... Agak keemasan?",
  ui_story_5063_50631701_15_dialog_content = "Eh... Kamu... Kamu tampak...",
  ui_story_5063_50631701_16_dialog_content = "Begini penampilanmu sekarang!",
  ui_story_5063_50631701_17_dialog_content = "Siapa kamu...?",
  ui_story_5063_50631701_18_dialog_content = "Saya adalah temanmu, PlayerName!",
  ui_story_5063_50631701_19_dialog_content = "Tapi itu tidak penting. Yang penting adalah... kamu harus ingat siapa dirimu!",
  ui_story_5063_50631701_20_dialog_content = "Aku... aku adalah diriku. Irridon Novek, seorang Ksatria Keadilan dari Lumopolis.",
  ui_story_5063_50631701_21_dialog_content = "Lihat cermin ini! Ini menunjukkan wajahmu!",
  ui_story_5063_50631701_22_dialog_content = "Ini... pantulan saya? Kau pasti bercanda! Mengapa saya terlihat seperti Hakim Ketua?",
  ui_story_5063_50631701_23_dialog_content = "Karena kamu sebenarnya Hakim Ketua!",
  ui_story_5063_50631701_24_dialog_content = "Saya ini Hakim Ketua yang sebenarnya? Lalu siapa wanita tadi?",
  ui_story_5063_50631701_25_dialog_content = "Dia... juga kamu, tetapi hanya sebagian dari dirimu. Dia adalah versi dirimu yang diidealkan yang ingin kamu jadikan dalam dunia nyata...",
  ui_story_5063_50631701_26_dialog_content = "Tapi dia sebenarnya bukan kamu! Karena kamu telah mencampurkan terlalu banyak ide orang lain ke dalam ekspektasi diri kamu sendiri.",
  ui_story_5063_50631701_27_dialog_content = "Kembalilah pada dirimu yang sebenarnya!",
  ui_story_5063_50631701_28_dialog_content = "<size=45>Bangun sekarang!</size>",
  ui_story_5063_50631701_29_dialog_content = "...",
  ui_story_5063_50631701_30_dialog_content = "Kenapa kamu menyuruhku untuk \"bangun\"?",
  ui_story_5063_50631701_31_dialog_content = "Jika ini memang mimpi, mungkin saatnya aku benar-benar bangun.",
  ui_story_5063_50631701_32_dialog_content = "Nah, sekarang kau...",
  ui_story_5063_50631701_33_dialog_content = "Aku ingin tahu apakah kamu akan melakukan hal yang sama?",
  ui_story_5063_50631701_34_dialog_content = "Sekarang setelah kupikirkan, semua yang telah kualami... Orang-orang itu dan kasus mereka... Memang ada sesuatu yang sedikit aneh tentang mereka.",
  ui_story_5063_50631701_35_dialog_content = "Tapi jika ini memang mimpi, bagaimana cara saya untuk bangun?",
  ui_story_5063_50631701_36_dialog_content = "...Aku harus menemukannya. Aku yang lain.",
  ui_story_5063_50631801_1_dialog_content = "<color=#e8d9bb>Kriek—</color>",
  ui_story_5063_50631801_2_dialog_content = "Kamu? Bagaimana kamu bisa masuk ke sini?",
  ui_story_5063_50631801_3_dialog_content = "Kasus yang melibatkan penjahat yang dikenal sebagai Paloma telah diselesaikan. Katakan padaku, Hakim Ketua, apakah Anda puas dengan penampilan saya?",
  ui_story_5063_50631801_4_dialog_content = "Kamu terlalu ragu-ragu. Kalau bukan karena campur tanganku, kamu pasti akan membuat kesalahan yang tak bisa dimaafkan.",
  ui_story_5063_50631801_5_dialog_content = "Kalau saja kamu mengikuti perintahku sejak awal, pasti semuanya akan berjalan lebih lancar.",
  ui_story_5063_50631801_6_dialog_content = "\"Lebih halus\"? Maksudmu menggantikan aku, ya?",
  ui_story_5063_50631801_7_dialog_content = "Jadi, akhirnya kau mulai mengingat...",
  ui_story_5063_50631801_8_dialog_content = "Saya mengerti... Menggantikan saya adalah rencana Anda sejak awal, bukan?",
  ui_story_5063_50631801_9_dialog_content = "Sayangnya, aku tidak akan membiarkan itu terjadi, sekarang atau kapanpun!",
  ui_story_5063_50631801_10_dialog_content = "Tidak ada gunanya melawan lebih jauh lagi. Aku adalah putri sempurna yang selalu diinginkan ayah, bukan kamu.",
  ui_story_5063_50631801_11_dialog_content = "Hanya saya yang pantas menjadi Hakim Ketua sejati Lumopolis!",
  ui_story_5063_50631801_12_dialog_content = "Sebaliknya, kamu hanya berhasil membantu dan mendukung kejahatan! Pengorbanan Ayah sia-sia untuk orang sepertimu!",
  ui_story_5063_50631801_13_dialog_content = "Benarkah itu? Terima kasih... Saya rasa saya sedikit lebih mengerti ayah sekarang.",
  ui_story_5063_50631801_14_dialog_content = "Saya menyadari sekarang bahwa saya selalu ingin mengulang kasus-kasus lama ayah saya, untuk memperbaiki kesalahan-kesalahannya serta kesalahan Balai Kehakiman...",
  ui_story_5063_50631801_15_dialog_content = "Tapi yang paling ingin saya adili... Bukanlah persidangan balas dendam Paloma.",
  ui_story_5063_50631801_16_dialog_content = "Tapi justru tradisi sombong dan berprasangka dari Lumopolis!",
  ui_story_5063_50631801_17_dialog_content = "Bisakah kamu mendengar dirimu sendiri sekarang? Bagaimana kamu bisa mengklaim bahwa keputusan ayah itu salah?!",
  ui_story_5063_50631801_18_dialog_content = "Ayah telah mengambil banyak keputusan yang masuk akal di masanya, tetapi bahkan dia pun membuat kesalahan. Kesalahan-kesalahan itu menyebabkan putusan yang salah, yang pada gilirannya menyebabkan kematian orang-orang yang tidak bersalah!",
  ui_story_5063_50631801_19_dialog_content = "Dia seharusnya bertanggung jawab atas kesalahannya di pengadilan, tetapi kematiannya mengakhiri segala penyelidikan.",
  ui_story_5063_50631801_20_dialog_content = "Tapi sekarang, akhirnya aku tahu apa yang menghalangi ayahku untuk mengambil keputusan yang lebih baik.",
  ui_story_5063_50631801_21_dialog_content = "Sebuah penyakit mengalir dalam darahnya, penyakit yang telah menjangkiti seluruh Lumopolis sepanjang sejarah panjangnya...",
  ui_story_5063_50631801_22_dialog_content = "Penyakit yang mengintai di dalam alam bawah sadar kita, baik milikmu maupun milikku!",
  ui_story_5063_50631801_23_dialog_content = "Ini adalah kebanggaan! Kebanggaan inilah yang menjadi akar dari korupsi Lumopolis, dan dengan menghakimi kebanggaan itu, aku akan membersihkannya dari jiwaku sendiri!",
  ui_story_5063_50631801_24_dialog_content = "Kamu hanya menentang ayahmu karena rasa sakit hati! Kamu masih lebih takut padanya daripada apapun!",
  ui_story_5063_50631801_25_dialog_content = "Aku mengakui bahwa dulu aku terlalu takut untuk menghadapinya.",
  ui_story_5063_50631801_26_dialog_content = "Dia mungkin bukan ayah yang baik... Tapi aku tahu bahwa dia telah berusaha sebaik mungkin untukku.",
  ui_story_5063_50631801_27_dialog_content = "Inilah mengapa saya tidak akan pernah bisa memaafkan tradisi yang memenjarakannya sepanjang hidupnya!",
  ui_story_5063_50631801_28_dialog_content = "Kalau bukan karena mereka, kita mungkin bisa lebih seperti Pam dan ayahnya...",
  ui_story_5063_50631801_29_dialog_content = "Apakah kamu kehilangan akal? Apakah kamu benar-benar iri pada penjahat-penjahat itu?!",
  ui_story_5063_50631801_30_dialog_content = "Masih ingatkah mengapa kamu ingin menjadi Hakim Ketua?",
  ui_story_5063_50631801_31_dialog_content = "Untuk melanjutkan jejak ayahku dan mewarisi peninggalannya, tentu saja!",
  ui_story_5063_50631801_32_dialog_content = "Alasan saya berbeda. Saya menjadi Ketua Hakim untuk melindungi Lumopolis dan penduduknya...",
  ui_story_5063_50631801_33_dialog_content = "Inilah sebabnya aku tak akan pernah membiarkanmu berbuat semaumu!",
  ui_story_5063_50631801_34_dialog_content = "Sekarang pergilah, agar kota ini akhirnya bisa bebas dari kesombongan jahatmu!",
  ui_story_5063_50631802_1_dialog_content = "Tidak——",
  ui_story_5063_50631802_2_dialog_content = "Aku adalah putri ideal ayah, bukan kamu! Bagaimana mungkin aku bisa kalah darimu?!",
  ui_story_5063_50631802_3_dialog_content = "Karena visi kamu tentang \"anak perempuan ideal\" tercipta saat aku belum mengerti ayahku.",
  ui_story_5063_50631802_4_dialog_content = "Dengan bersikap keras dan tidak kenal belas kasihan pada orang lain dan diri saya sendiri, serta menilai kasus dengan ketat sesuai dengan hukum, saya pikir saya bisa menjadi putri yang selalu diinginkan ayah saya.",
  ui_story_5063_50631802_5_dialog_content = "Tapi aku salah. Setelah mengulas kasus-kasus lama ayah, aku menemukan bahwa meskipun sikapnya yang dingin dan acuh tak acuh...",
  ui_story_5063_50631802_6_dialog_content = "Ayah berusaha keras mengumpulkan sebanyak mungkin bukti sebelum persidangan, agar ia dapat memberikan putusan yang paling adil.",
  ui_story_5063_50631802_7_dialog_content = "Namun, pemikiran \"keadilan\" miliknya masih ternoda oleh kesombongan tradisi kuno yang usang.",
  ui_story_5063_50631802_8_dialog_content = "Itulah mengapa semua orang mengatakan bahwa ayah adalah Hakim Ketua terbaik dalam sejarah Lumopolis, dan bahwa aku tidak akan pernah bisa menyamai kehebatannya.",
  ui_story_5063_50631802_9_dialog_content = "...Aku tidak pernah benar-benar memahami dia atau cara berpikirnya.",
  ui_story_5063_50631802_10_dialog_content = "Namun, sebagai hakim, selama kita terus berusaha sebaik mungkin, hukum akan kembali pada keadaan seimbang.",
  ui_story_5063_50631802_11_dialog_content = "Ayah telah memberi saya dua kesempatan untuk hidup sekarang. Meskipun pengorbanannya mungkin tidak cukup untuk mengembalikan keseimbangan di antara kami...",
  ui_story_5063_50631802_12_dialog_content = "Aku bersedia menerima itu.",
